/* DAWAH X — ahmad, অধ্যায় 108 · খণ্ড 108 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][108]=[[21401,21401,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ فِي الْفِضَّةِ وَالذَّهَبِ مَا نَزَلَ قَالُوا فَأَيَّ الْمَالِ نَتَّخِذُ قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا أَعْلَمُ ذَلِكَ لَكُمْ قَالَ فَأَوْضَعَ عَلَى بَعِيرٍ فَأَدْرَكَهُ وَأَنَا فِي ‏ ‏أَثَرِهِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيَّ الْمَالِ نَتَّخِذُ قَالَ ‏ ‏لِيَتَّخِذْ أَحَدُكُمْ قَلْبًا شَاكِرًا وَلِسَانًا ذَاكِرًا وَزَوْجَةً تُعِينُهُ عَلَى أَمْرِ الْآخِرَةِ ‏","","",""],[21402,21402,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْعَبْدَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ وَلَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَلَا يَزِيدُ فِي الْعُمُرِ إِلَّا الْبِرُّ ‏","","",""],[21403,21403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ ‏","","",""],[21404,21404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏أَبَا أَسْمَاءَ ‏ ‏وَذَكَرَ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا الطَّلَاقَ فِي غَيْرِ مَا ‏ ‏بَأْسٍ ‏ ‏فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ ‏","","",""],[21405,21405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ أَبِي عَبْدِ اللَّهِ ‏ ‏وَابْنُ جَعْفَرٍ يَعْنِي غُنْدَرًا ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَبِعَ جِنَازَةً فَصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا كَانَ لَهُ قِيرَاطَانِ قَالُوا وَمَا الْقِيرَاطَانِ قَالَ أَصْغَرُهُمَا مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21406,21406,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَتَكْذِبُونَ عَلَيَّ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[21407,21407,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْجُودِيِّ ‏ ‏عَنْ ‏ ‏بَلْجٍ ‏ ‏عَنْ ‏ ‏أَبِي شَيْبَةَ الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏قَاصَّ ‏ ‏النَّاسِ ‏ ‏بِقُسْطَنْطِينِيَّةَ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قُسْطَنْطِينِيَّةُ ‏","","",""],[21408,21408,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا ‏ ‏عَادَ ‏ ‏أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21409,21409,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21410,21410,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21411,21411,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمُرِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي ‏ ‏لَبِعُقْرِ ‏ ‏الْحَوْضِ يَوْمَ الْقِيَامَةِ أَذُودُ عَنْهُ النَّاسَ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏أَضْرِبُهُمْ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ قَالَ فَسُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَرْضِهِ فَقَالَ مِنْ مُقَامِي هَذَا إِلَى ‏ ‏عُمَانَ ‏ ‏وَسُئِلَ عَنْ شَرَابِهِ فَقَالَ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ يَصُبُّ فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَمُدَّانِهِ ‏ ‏مِنْ الْجَنَّةِ أَحَدُهُمَا ذَهَبٌ وَالْآخَرُ وَرِقٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[21412,21412,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ الْجَرْمِيُّ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏شَدَّادَ بْنَ أَوْسٍ ‏ ‏بَيْنَمَا هُوَ يَمْشِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَقِيعِ ‏ ‏مَرَّ عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏بَعْدَ مَا مَضَى مِنْ رَمَضَانَ ثَمَانِ عَشْرَةَ لَيْلَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21413,21413,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏أَنَّ ‏ ‏أَبَا أَسْمَاءَ الرَّحَبِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21414,21414,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الْمُسْلِمُ أَخَاهُ فَإِنَّهُ يَمْشِي فِي ‏ ‏خَرْفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21415,21415,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ أَوْ ‏ ‏إِنَّ ‏ ‏رَبِّي ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ مَشَارِقَهَا وَمَغَارِبَهَا وَإِنَّ أُمَّتِي سَيَبْلُغُ مُلْكُهَا مَا ‏ ‏زُوِيَ ‏ ‏لِي مِنْهَا وَأُعْطِيتُ الْكَنْزَيْنِ ‏ ‏الْأَحْمَرَ ‏ ‏وَالْأَبْيَضَ ‏ ‏وَإِنِّي سَأَلْتُ رَبِّي لِأُمَّتِي أَنْ لَا يُهْلِكَهَا بِسَنَةٍ بِعَامَّةٍ وَلَا يُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ سِوَى أَنْفُسِهِمْ فَيَسْتَبِيحَ ‏ ‏بَيْضَتَهُمْ ‏ ‏حَتَّى يَكُونَ بَعْضُهُمْ ‏ ‏يَسْبِي ‏ ‏بَعْضًا وَبَعْضُهُمْ يُهْلِكُ بَعْضًا وَلَوْ اجْتَمَعَ عَلَيْهِمْ مَنْ بَيْنَ ‏ ‏أَقْطَارِهَا ‏ ‏أَوْ قَالَ مَنْ بِأَقْطَارِهَا ‏ ‏أَلَا وَإِنِّي أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ وَإِذَا وُضِعَ السَّيْفُ فِي أُمَّتِي لَمْ يُرْفَعْ عَنْهَا إِلَى يَوْمِ الْقِيَامَةِ وَلَا تَقُومُ السَّاعَةُ حَتَّى تَلْحَقَ قَبَائِلُ مِنْ أُمَّتِي بِالْمُشْرِكِينَ وَحَتَّى تَعْبُدَ قَبَائِلُ مِنْ أُمَّتِي الْأَوْثَانَ ‏","","",""],[21416,21416,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَمْلَاهُ عَلَيْنَا ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْضَلُ دِينَارٍ دِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى عِيَالِهِ وَدِينَارٌ يُنْفِقُهُ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ ‏ ‏قَالَ ‏ ‏ثُمَّ قَالَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏مِنْ قِبَلِهِ بَرًّا بِالْعِيَالِ ‏ ‏قَالَ وَأَيُّ رَجُلٍ أَعْظَمُ أَجْرًا مِنْ رَجُلٍ يُنْفِقُ عَلَى عِيَالِهِ صِغَارًا ‏ ‏يُعِفُّهُمْ ‏ ‏اللَّهُ بِهِ ‏","","",""],[21417,21417,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ شَهِدَ دَفْنَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْقِيرَاطَانِ ‏ ‏قَالَ أَصْغَرُهُمَا مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21418,21418,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ سُئِلَ ‏ ‏سَعِيدٌ ‏ ‏عَنْ الرَّجُلِ يَتْبَعُ جِنَازَةً مَا لَهُ مِنْ الْأَجْرِ ‏ ‏فَأَخْبَرَنَا عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏فَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏الْقِيرَاطِ ‏ ‏فَقَالَ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21419,21419,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ فَائِدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ أَمِيرِ عَشَرَةٍ إِلَّا أَتَى اللَّهَ عَزَّ وَجَلَّ مَغْلُولًا يَوْمَ الْقِيَامَةِ لَا يُطْلِقُهُ إِلَّا الْعَدْلُ وَمَا مِنْ أَحَدٍ ‏ ‏يَتَعَلَّمُ ‏ ‏الْقُرْآنَ ثُمَّ نَسِيَهُ إِلَّا لَقِيَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏أَجْذَمَ ‏","","",""],[21420,21420,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ بْنِ سَعِيدِ بْنِ سَعْدِ بْنِ عُبَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَخْبِرْنَا عَنْ يَوْمِ الْجُمُعَةِ مَاذَا فِيهِ مِنْ الْخَيْرِ قَالَ فِيهِ خَمْسُ ‏ ‏خِلَالٍ ‏ ‏فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ هَبَطَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ تُوُفِّيَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ سَاعَةٌ لَا يَسْأَلُ اللَّهَ عَبْدٌ فِيهَا شَيْئًا إِلَّا آتَاهُ اللَّهُ إِيَّاهُ مَا لَمْ يَسْأَلْ ‏ ‏مَأْثَمًا ‏ ‏أَوْ قَطِيعَةَ رَحِمٍ وَفِيهِ تَقُومُ السَّاعَةُ مَا مِنْ مَلَكٍ مُقَرَّبٍ وَلَا سَمَاءٍ وَلَا أَرْضٍ وَلَا جِبَالٍ وَلَا حَجَرٍ إِلَّا وَهُوَ يُشْفِقُ مِنْ يَوْمِ الْجُمُعَةِ ‏","","",""],[21421,21421,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏دُلَّنِي عَلَى ‏ ‏صَدَقَةٍ ‏ ‏قَالَ اسْقِ الْمَاءَ ‏","","",""],[21422,21422,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏أَنَّ أُمَّهُ مَاتَتْ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أُمِّي مَاتَتْ فَأَتَصَدَّقُ عَنْهَا قَالَ نَعَمْ قَالَ فَأَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ سَقْيُ الْمَاءِ ‏ ‏قَالَ ‏ ‏فَتِلْكَ سِقَايَةُ آلِ ‏ ‏سَعْدٍ ‏ ‏بِالْمَدِينَةِ ‏","","",""],[21423,21423,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عَمْرِو بْنِ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ وَجَدُوا فِي كُتُبِ ‏ ‏أَوْ فِي كِتَابِ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ ‏","","",""],[21424,21424,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏قُمْ عَلَى ‏ ‏صَدَقَةِ ‏ ‏بَنِي فُلَانٍ وَانْظُرْ لَا تَأْتِي يَوْمَ الْقِيَامَةِ ‏ ‏بِبَكْرٍ ‏ ‏تَحْمِلُهُ عَلَى ‏ ‏عَاتِقِكَ ‏ ‏أَوْ عَلَى كَاهِلِكَ ‏ ‏لَهُ ‏ ‏رُغَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ قَالَ يَا رَسُولَ اللَّهِ اصْرِفْهَا عَنِّي فَصَرَفَهَا عَنْهُ ‏","","",""],[21425,21425,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي شُمَيْلَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏رَدَّهُ إِلَى ‏ ‏سَعِيدٍ الصَّرَّافِ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ سَعْدِ بْنِ عُبَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا الْحَيَّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِحْنَةٌ ‏ ‏حُبُّهُمْ إِيمَانٌ وَبُغْضُهُمْ نِفَاقٌ ‏","","",""],[21426,21426,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ فَائدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَمِيرِ عَشَرَةٍ إِلَّا يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ مَغْلُولٌ لَا يَفُكُّهُ مِنْ ذَلِكَ الْغُلِّ إِلَّا الْعَدْلُ وَمَا مِنْ رَجُلٍ قَرَأَ الْقُرْآنَ فَنَسِيَهُ إِلَّا لَقِيَ اللَّهَ يَوْمَ يَلْقَاهُ وَهُوَ ‏ ‏أَجْذَمُ ‏","","",""],[21427,21427,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ نُعَيْمٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ وَإِنْ زَنَى وَإِنْ سَرَقَ ‏","","",""],[21428,21428,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رِعْيَةُ السُّحَيْمِيُّ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أُغِيرَ عَلَى وَلَدِي وَمَالِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا الْمَالُ فَقَدْ اقْتُسِمَ وَأَمَّا الْوَلَدُ فَاذْهَبْ مَعَهُ يَا ‏ ‏بِلَالُ ‏ ‏فَإِنْ عَرَفَ وَلَدَهُ فَادْفَعْهُ إِلَيْهِ قَالَ فَذَهَبَ مَعَهُ ‏ ‏فَأَرَاهُ إِيَّاهُ فَقَالَ تَعْرِفُهُ قَالَ نَعَمْ فَدَفَعَهُ فَذَهَبَ إِلَيْهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏يَرَوْنَ أَنَّهُ أَسْلَمَ قَبْلَ أَنْ يُغَارَ عَلَيْهِ ‏","","",""],[21429,21429,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏رِعْيَةَ السُّحَيْمِيِّ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَدِيمٍ ‏ ‏أَحْمَرَ فَأَخَذَ كِتَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَقَعَ ‏ ‏بِهِ دَلْوَهُ فَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏فَلَمْ يَدَعُوا لَهُ رَائِحَةً وَلَا ‏ ‏سَارِحَةً ‏ ‏وَلَا أَهْلًا وَلَا مَالًا إِلَّا أَخَذُوهُ وَانْفَلَتَ عُرْيَانًا عَلَى فَرَسٍ لَهُ لَيْسَ عَلَيْهِ قِشْرَةٌ حَتَّى يَنْتَهِيَ إِلَى ابْنَتِهِ وَهِيَ مُتَزَوِّجَةٌ فِي ‏ ‏بَنِي هِلَالٍ ‏ ‏وَقَدْ أَسْلَمَتْ وَأَسْلَمَ أَهْلُهَا وَكَانَ مَجْلِسُ الْقَوْمِ بِفِنَاءِ بَيْتِهَا فَدَارَ حَتَّى دَخَلَ عَلَيْهَا مِنْ وَرَاءِ الْبَيْتِ قَالَ فَلَمَّا رَأَتْهُ أَلْقَتْ عَلَيْهِ ثَوْبًا قَالَتْ مَا لَكَ قَالَ كُلُّ الشَّرِّ نَزَلَ بِأَبِيكِ مَا تُرِكَ لَهُ رَائِحَةٌ وَلَا ‏ ‏سَارِحَةٌ ‏ ‏وَلَا أَهْلٌ وَلَا مَالٌ إِلَّا وَقَدْ أُخِذَ قَالَتْ دُعِيتَ إِلَى الْإِسْلَامِ قَالَ أَيْنَ بَعْلُكِ قَالَتْ فِي الْإِبِلِ قَالَ فَأَتَاهُ فَقَالَ مَا لَكَ قَالَ كُلُّ الشَّرِّ قَدْ نَزَلَ بِهِ مَا تُرِكَتْ لَهُ رَائِحَةٌ وَلَا ‏ ‏سَارِحَةٌ ‏ ‏وَلَا أَهْلٌ وَلَا مَالٌ إِلَّا وَقَدْ أُخِذَ وَأَنَا أُرِيدُ ‏ ‏مُحَمَّدًا ‏ ‏أُبَادِرُهُ قَبْلَ أَنْ يُقَسِّمَ أَهْلِي وَمَالِي قَالَ فَخُذْ رَاحِلَتِي بِرَحْلِهَا قَالَ لَا حَاجَةَ لِي فِيهَا قَالَ فَأَخَذَ ‏ ‏قَعُودَ ‏ ‏الرَّاعِي وَزَوَّدَهُ ‏ ‏إِدَاوَةً ‏ ‏مِنْ مَاءٍ قَالَ وَعَلَيْهِ ثَوْبٌ إِذَا غَطَّى بِهِ وَجْهَهُ خَرَجَتْ ‏ ‏اسْتُهُ ‏ ‏وَإِذَا غَطَّى ‏ ‏اسْتَهُ ‏ ‏خَرَجَ وَجْهُهُ وَهُوَ يَكْرَهُ أَنْ يُعْرَفَ حَتَّى انْتَهَى إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَعَقَلَ رَاحِلَتَهُ ثُمَّ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ بِحِذَائِهِ حَيْثُ ‏ ‏يُصَلِّي فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَجْرَ قَالَ يَا رَسُولَ اللَّهِ ابْسُطْ يَدَيْكَ فَلْأُبَايِعْكَ فَبَسَطَهَا فَلَمَّا أَرَادَ أَنْ يَضْرِبَ عَلَيْهَا قَبَضَهَا إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَفَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ ثَلَاثًا قَبَضَهَا إِلَيْهِ وَيَفْعَلُهُ فَلَمَّا كَانَتْ الثَّالِثَةُ قَالَ مَنْ أَنْتَ قَالَ ‏ ‏رِعْيَةُ السُّحَيْمِيُّ ‏ ‏قَالَ فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَضُدَهُ ثُمَّ رَفَعَهُ ثُمَّ قَالَ يَا مَعْشَرَ الْمُسْلِمِينَ ‏ ‏هَذَا ‏ ‏رِعْيَةُ السُّحَيْمِيُّ ‏ ‏الَّذِي كَتَبْتُ إِلَيْهِ فَأَخَذَ كِتَابِي فَرَقَعَ بِهِ دَلْوَهُ فَأَخَذَ ‏ ‏يَتَضَرَّعُ ‏ ‏إِلَيْهِ قُلْتُ يَا رَسُولَ اللَّهِ أَهْلِي وَمَالِي قَالَ أَمَّا مَالُكَ فَقَدْ قُسِّمَ وَأَمَّا أَهْلُكَ فَمَنْ قَدَرْتَ عَلَيْهِ مِنْهُمْ فَخَرَجَ فَإِذَا ابْنُهُ قَدْ عَرَفَ الرَّاحِلَةَ وَهُوَ قَائِمٌ عِنْدَهَا فَرَجَعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَذَا ابْنِي فَقَالَ يَا ‏ ‏بِلَالُ ‏ ‏اخْرُجْ مَعَهُ فَسَلْهُ أَبُوكَ هَذَا فَإِنْ قَالَ نَعَمْ فَادْفَعْهُ إِلَيْهِ فَخَرَجَ ‏ ‏بِلَالٌ ‏ ‏إِلَيْهِ فَقَالَ أَبُوكَ هَذَا قَالَ نَعَمْ فَرَجَعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا رَأَيْتُ أَحَدًا اسْتَعْبَرَ إِلَى صَاحِبِهِ فَقَالَ ذَاكَ ‏ ‏جَفَاءُ ‏ ‏الْأَعْرَابِ ‏","","",""],[21430,21430,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هَمَّامٍ ‏ ‏قَالَ ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْفِهْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏حُنَيْنٍ ‏ ‏فَسِرْنَا فِي يَوْمٍ ‏ ‏قَائِظٍ ‏ ‏شَدِيدِ الْحَرِّ فَنَزَلْنَا تَحْتَ ظِلَالِ الشَّجَرِ فَلَمَّا زَالَتْ الشَّمْسُ لَبِسْتُ لَأْمَتِي وَرَكِبْتُ فَرَسِي فَانْطَلَقْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي ‏ ‏فُسْطَاطِهِ ‏ ‏فَقُلْتُ السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ وَرَحْمَةُ اللَّهِ حَانَ الرَّوَاحُ فَقَالَ أَجَلْ فَقَالَ يَا ‏ ‏بِلَالُ ‏ ‏فَثَارَ مِنْ تَحْتِ ‏ ‏سَمُرَةٍ ‏ ‏كَأَنَّ ظِلَّهُ ظِلُّ طَائِرٍ فَقَالَ لَبَّيْكَ وَسَعْدَيْكَ وَأَنَا فِدَاؤُكَ فَقَالَ ‏ ‏أَسْرِجْ ‏ ‏لِي فَرَسِي فَأَخْرَجَ ‏ ‏سَرْجًا ‏ ‏دَفَّتَاهُ ‏ ‏مِنْ لِيفٍ لَيْسَ فِيهِمَا أَشَرٌ وَلَا ‏ ‏بَطَرٌ ‏ ‏قَالَ ‏ ‏فَأَسْرَجَ ‏ ‏قَالَ فَرَكِبَ وَرَكِبْنَا فَصَافَفْنَاهُمْ عَشِيَّتَنَا وَلَيْلَتَنَا ‏ ‏فَتَشَامَّتِ الْخَيْلَانِ فَوَلَّى الْمُسْلِمُونَ ‏ ‏مُدْبِرِينَ ‏ ‏كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا عِبَادَ اللَّهِ أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ قَالَ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ قَالَ ثُمَّ اقْتَحَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ فَرَسِهِ فَأَخَذَ كَفًّا مِنْ تُرَابٍ فَأَخْبَرَنِي الَّذِي كَانَ أَدْنَى إِلَيْهِ مِنِّي ضَرَبَ بِهِ وُجُوهَهُمْ وَقَالَ ‏ ‏شَاهَتْ ‏ ‏الْوُجُوهُ فَهَزَمَهُمْ اللَّهُ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبْنَاؤُهُمْ عَنْ آبَائِهِمْ أَنَّهُمْ قَالُوا ‏ ‏لَمْ يَبْقَ مِنَّا أَحَدٌ إِلَّا امْتَلَأَتْ عَيْنَاهُ وَفَمُهُ تُرَابًا وَسَمِعْنَا ‏ ‏صَلْصَلَةً ‏ ‏بَيْنَ السَّمَاءِ وَالْأَرْضِ كَإِمْرَارِ الْحَدِيدِ عَلَى ‏ ‏الطَّسْتِ ‏ ‏الْحَدِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَسَارٍ أَبِي هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْفِهْرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏حُنَيْنٍ ‏ ‏فَسِرْنَا فِي يَوْمٍ ‏ ‏قَائِظٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[21431,21431,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ الْغَطَفَانِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏لَا تَعْجِزْ عَنْ أَرْبَعِ رَكَعَاتٍ مِنْ أَوَّلِ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21432,21432,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنَا ‏ ‏مَكْحُولٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ الْغَطَفَانِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏لَا تَعْجِزْ عَنْ أَرْبَعِ رَكَعَاتٍ مِنْ أَوَّلِ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21433,21433,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زَيْدٍ يَعْنِي ثَابِتَ بْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏بَرْدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنِ ‏ ‏ابْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏قَيْسٍ الْجُذَامِيِّ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏صَلِّ لِي أَرْبَعَ رَكَعَاتٍ أَوَّلَ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21434,21434,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏صَلِّ لِي يَا ابْنَ ‏ ‏آدَمَ ‏ ‏أَرْبَعًا فِي أَوَّلِ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21435,21435,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنِ ‏ ‏ابْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏نُعَيمِ بْنِ هَمِّارٍ الْغَطَفَانِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏صَلِّ لِي أَرْبَعَ رَكَعَاتٍ مِنْ أَوَّلِ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21436,21436,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ابْنَ ‏ ‏آدَمَ ‏ ‏لَا تَعْجِزْ عَنْ أَرْبَعِ رَكَعَاتٍ أَوَّلَ النَّهَارِ أَكْفِكَ آخِرَهُ ‏","","",""],[21437,21437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَكْحُولٌ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَبُّكُمْ تَبَارَكَ وَتَعَالَى ‏ ‏ابْنَ ‏ ‏آدَمَ ‏ ‏صَلِّ لِي أَرْبَعَ رَكَعَاتٍ أَوَّلَ النَّهَارِ أَكْفِكَ آخِرَهُ ‏ ‏لَيْسَ ‏ ‏بِالشَّامِ ‏ ‏رَجُلٌ أَصَحُّ حَدِيثًا مِنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ ‏","","",""],[21438,21438,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الشُّهَدَاءِ أَفْضَلُ قَالَ ‏ ‏الَّذِينَ إِنْ يُلْقَوْا فِي الصَّفِّ يَلْفِتُونَ وُجُوهَهُمْ حَتَّى يُقْتَلُوا أُولَئِكَ يَنْطَلِقُونَ فِي ‏ ‏الْغُرَفِ ‏ ‏الْعُلَى مِنْ الْجَنَّةِ وَيَضْحَكُ إِلَيْهِمْ رَبُّهُمْ وَإِذَا ضَحِكَ رَبُّكَ إِلَى عَبْدٍ فِي الدُّنْيَا فَلَا حِسَابَ عَلَيْهِ ‏","","",""],[21439,21439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏بِالْكُوفَةِ ‏ ‏وَقَالَ لَنَا فِيهِ ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَأَمَّا أَبِي فَحَدَّثَنَاهُ عَنْهُ وَلَمْ يَذْكُرْ ‏ ‏الزُّهْرِيَّ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏بِالْكُوفَةِ ‏ ‏جَعَلَهُ لَنَا عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏ثُمَّ رَجَعَ إِلَى حَدِيثِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ إِسْمَاعِيلَ ‏ ‏أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ وَحْدَهُ عَيْنًا إِلَى ‏ ‏قُرَيْشٍ ‏ ‏قَالَ فَجِئْتُ إِلَى خَشَبَةِ ‏ ‏خُبَيْبٍ ‏ ‏وَأَنَا أَتَخَوَّفُ الْعُيُونَ فَرَقَيْتُ فِيهَا فَحَلَلْتُ ‏ ‏خُبَيْبًا ‏ ‏فَوَقَعَ إِلَى الْأَرْضِ ‏ ‏فَانْتَبَذْتُ ‏ ‏غَيْرَ بَعِيدٍ ثُمَّ الْتَفَتُّ فَلَمْ أَرَ ‏ ‏خُبَيْبًا ‏ ‏وَلَا كَأَنَّمَا ابْتَلَعَتْهُ الْأَرْضُ فَلَمْ يُرَ ‏ ‏لِخُبَيْبٍ ‏ ‏أَثَرٌ حَتَّى السَّاعَةِ ‏","","",""],[21440,21440,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[21441,21441,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ عُضْوًا فِي الْمُصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[21442,21442,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنَا ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏كُلَيْبَ بْنَ صُبْحٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الزِّبْرِقَانَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَمِّهِ ‏ ‏عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فَنَامَ عَنْ صَلَاةِ الصُّبْحِ حَتَّى طَلَعَتْ الشَّمْسُ لَمْ يَسْتَيْقِظُوا وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ بِالرَّكْعَتَيْنِ فَرَكَعَهُمَا ثُمَّ أَقَامَ الصَّلَاةَ فَصَلَّى ‏","","",""],[21443,21443,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَمْرٍو الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ الْيَمَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ وَالْعِمَامَةِ ‏","","",""],[21444,21444,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏ ‏وَالْخِمَارِ ‏","","",""],[21445,21445,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[21446,21446,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفِ شَاةٍ فَدُعِيَ إِلَى الصَّلَاةِ فَطَرَحَ السِّكِّينَ وَلَمْ يَتَوَضَّأْ ‏","","",""],[21447,21447,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفٍ ثُمَّ دُعِيَ إِلَى الصَّلَاةِ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[21448,21448,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏جَعْفَرَ بْنَ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[21449,21449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ حَبِيبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ زُغْبٍ الْإِيَادِيَّ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏نَزَلَ عَلَيَّ ‏ ‏عَبْدُ اللَّهِ بْنُ حَوَالَةَ الْأَزْدِيُّ ‏ ‏فَقَالَ لِي وَإِنَّهُ لَنَازِلٌ عَلَيَّ فِي بَيْتِي بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَوْلَ ‏ ‏الْمَدِينَةِ ‏ ‏عَلَى أَقْدَامِنَا لِنَغْنَمَ فَرَجَعْنَا وَلَمْ نَغْنَمْ شَيْئًا وَعَرَفَ الْجَهْدَ فِي وُجُوهِنَا فَقَامَ فِينَا فَقَالَ ‏ ‏اللَّهُمَّ لَا ‏ ‏تَكِلْهُمْ ‏ ‏إِلَيَّ فَأَضْعُفَ وَلَا ‏ ‏تَكِلْهُمْ ‏ ‏إِلَى أَنْفُسِهِمْ فَيَعْجِزُوا عَنْهَا وَلَا ‏ ‏تَكِلْهُمْ ‏ ‏إِلَى النَّاسِ فَيَسْتَأْثِرُوا عَلَيْهِمْ ثُمَّ قَالَ لَيُفْتَحَنَّ لَكُمْ ‏ ‏الشَّامُ ‏ ‏وَالرُّومُ ‏ ‏وَفَارِسُ ‏ ‏أَوْ ‏ ‏الرُّومُ ‏ ‏وَفَارِسُ ‏ ‏حَتَّى يَكُونَ لِأَحَدِكُمْ مِنْ الْإِبِلِ كَذَا وَكَذَا وَمِنْ الْبَقَرِ كَذَا وَكَذَا وَمِنْ الْغَنَمِ حَتَّى يُعْطَى أَحَدُهُمْ مِائَةَ دِينَارٍ فَيَسْخَطَهَا ثُمَّ وَضَعَ يَدَهُ عَلَى رَأْسِي ‏ ‏أَوْ ‏ ‏هَامَتِي ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏إِذَا رَأَيْتَ الْخِلَافَةَ قَدْ نَزَلَتْ الْأَرْضَ الْمُقَدَّسَةَ فَقَدْ دَنَتْ الزَّلَازِلُ وَالْبَلَايَا وَالْأُمُورُ الْعِظَامُ وَالسَّاعَةُ يَوْمَئِذٍ أَقْرَبُ إِلَى النَّاسِ مِنْ يَدَيَّ هَذِهِ مِنْ رَأْسِكَ ‏","","",""],[21450,21450,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ الْأَزْدِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ نَجَا مِنْ ثَلَاثٍ فَقَدْ نَجَا قَالَهُ ثَلَاثَ مَرَّاتٍ قَالُوا مَاذَا يَا رَسُولَ اللَّهِ قَالَ مَوْتِي وَمِنْ قَتْلِ خَلِيفَةٍ ‏ ‏مُصْطَبِرٍ ‏ ‏بِالْحَقِّ ‏ ‏يُعْطِيهِ ‏ ‏وَالدَّجَّالِ ‏","","",""],[21451,21451,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏وَعَلِيُّ بْنُ عَيَّاشٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُمَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ حَوَالَةَ الْأَزْدِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَيَكُونُ أَجْنَادٌ ‏ ‏مُجَنَّدَةٌ ‏ ‏شَامٌ ‏ ‏وَيَمَنٌ ‏ ‏وَعِرَاقٌ ‏ ‏وَاللَّهُ أَعْلَمُ بِأَيِّهَا بَدَأَ ‏ ‏وَعَلَيْكُمْ ‏ ‏بِالشَّامِ ‏ ‏أَلَا وَعَلَيْكُمْ ‏ ‏بِالشَّامِ ‏ ‏أَلَا وَعَلَيْكُمْ ‏ ‏بِالشَّامِ ‏ ‏فَمَنْ كَرِهَ فَعَلَيْهِ ‏ ‏بِيَمَنِهِ ‏ ‏وَلْيَسْقِ فِي ‏ ‏غُدُرِهِ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ تَوَكَّلَ لِي ‏ ‏بِالشَّامِ ‏ ‏وَأَهْلِهِ ‏","","",""],[21452,21452,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ ‏ ‏أَتَانِي ‏ ‏الْوَلِيدُ ‏ ‏أَنَا وَصَاحِبٌ لِي قَالَ فَقَالَ لَنَا هَلُمَّا فَأَنْتُمَا أَشَبُّ مِنِّي سِنًّا وَأَوْعَى لِلْحَدِيثِ مِنِّي قَالَ فَانْطَلَقَ بِنَا إِلَى ‏ ‏بِشْرِ بْنِ عَاصِمٍ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏أَبُو الْعَالِيَةِ ‏ ‏تُحَدِّثُ هَذَيْنِ حَدِيثَكَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏اللَّيْثِيُّ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَكَانَ مِنْ رَهْطِهِ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏قَالَ فَأَغَارَتْ عَلَى قَوْمٍ قَالَ فَشَذَّ مِنْ الْقَوْمِ رَجُلٌ قَالَ فَاتَّبَعَهُ رَجُلٌ مِنْ ‏ ‏السَّرِيَّةِ ‏ ‏شَاهِرًا سَيْفَهُ قَالَ فَقَالَ الشَّاذُّ مِنْ الْقَوْمِ إِنِّي مُسْلِمٌ قَالَ فَلَمْ يَنْظُرْ فِيمَا قَالَ فَضَرَبَهُ فَقَتَلَهُ قَالَ ‏ ‏فَنَمَى ‏ ‏الْحَدِيثُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ فِيهِ قَوْلًا شَدِيدًا فَبَلَغَ الْقَاتِلَ قَالَ فَبَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ قَالَ الْقَاتِلُ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا قَالَ الَّذِي قَالَ إِلَّا ‏ ‏تَعَوُّذًا ‏ ‏مِنْ الْقَتْلِ قَالَ فَأَعْرَضَ عَنْهُ وَعَمَّنْ قِبَلَهُ مِنْ النَّاسِ وَأَخَذَ فِي خُطْبَتِهِ ثُمَّ قَالَ أَيْضًا يَا رَسُولَ اللَّهِ مَا قَالَ الَّذِي قَالَ إِلَّا ‏ ‏تَعَوُّذًا ‏ ‏مِنْ الْقَتْلِ فَأَعْرَضَ عَنْهُ وَعَمَّنْ قِبَلَهُ مِنْ النَّاسِ وَأَخَذَ فِي خُطْبَتِهِ ثُمَّ لَمْ يَصْبِرْ فَقَالَ الثَّالِثَةَ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا قَالَ إِلَّا تَعَوُّذًا مِنْ الْقَتْلِ فَأَقْبَلَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُعْرَفُ ‏ ‏الْمَسَاءَةُ ‏ ‏فِي وَجْهِهِ قَالَ لَهُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَبَى عَلَى مَنْ قَتَلَ مُؤْمِنًا ثَلَاثَ مَرَّاتٍ ‏","","",""],[21453,21453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ أَبِي الرَّبِيعِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَسْجِدَ ‏ ‏دِمَشْقَ ‏ ‏فَرَأَيْتُ نَاسًا مُجْتَمِعِينَ وَشَيْخٌ يُحَدِّثُهُمْ قُلْتُ مَنْ هَذَا قَالُوا هَذَا ‏ ‏سَهْلُ ابْنُ الْحَنْظَلِيَّةِ ‏ ‏فَسَمِعْتُهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَكَلَ لَحْمًا فَلْيَتَوَضَّأْ ‏","","",""],[21454,21454,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ يَزِيدَ أَبُو مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِيهِ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْفَغْوَاءِ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ أَرَادَ أَنْ يَبْعَثَنِي بِمَالٍ إِلَى ‏ ‏أَبِي سُفْيَانَ ‏ ‏يَقْسِمُهُ فِي ‏ ‏قُرَيْشٍ ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ الْفَتْحِ قَالَ فَقَالَ الْتَمِسْ صَاحِبًا قَالَ فَجَاءَنِي ‏ ‏عَمْرُو بْنُ أُمَيَّةَ الضَّمْرِيُّ ‏ ‏قَالَ بَلَغَنِي أَنَّكَ تُرِيدُ الْخُرُوجَ وَتَلْتَمِسُ صَاحِبًا قَالَ قُلْتُ أَجَلْ قَالَ فَأَنَا لَكَ صَاحِبٌ قَالَ فَجِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ قَدْ وَجَدْتُ صَاحِبًا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَجَدْتَ صَاحِبًا فَآذِنِّي قَالَ فَقَالَ مَنْ قُلْتُ ‏ ‏عَمْرُو بْنُ أُمَيَّةَ الضَّمْرِيُّ ‏ ‏قَالَ فَقَالَ إِذَا هَبَطْتَ بِلَادَ قَوْمِهِ فَاحْذَرْهُ فَإِنَّهُ قَدْ قَالَ الْقَائِلُ أَخُوكَ الْبَكْرِيُّ وَلَا تَأْمَنْهُ قَالَ فَخَرَجْنَا حَتَّى إِذَا جِئْتُ ‏ ‏الْأَبْوَاءَ ‏ ‏فَقَالَ لِي إِنِّي أُرِيدُ حَاجَةً إِلَى قَوْمِي ‏ ‏بِوَدَّانَ ‏ ‏فَتَلَبَّثْ لِي قَالَ قُلْتُ رَاشِدًا فَلَمَّا وَلَّى ذَكَرْتُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَدَدْتُ عَلَى بَعِيرِي ثُمَّ خَرَجْتُ أُوضِعُهُ حَتَّى إِذَا كُنْتُ ‏ ‏بَالْأَصَافِرِ ‏ ‏إِذَا هُوَ يُعَارِضُنِي فِي ‏ ‏رَهْطِهِ ‏ ‏قَالَ وَأَوْضَعْتُ فَسَبَقْتُهُ فَلَمَّا رَآنِي قَدْ فُتُّهُ انْصَرَفُوا وَجَاءَنِي قَالَ كَانَتْ لِي إِلَى قَوْمِي حَاجَةٌ قَالَ قُلْتُ أَجَلْ فَمَضَيْنَا حَتَّى قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏فَدَفَعْتُ الْمَالَ إِلَى ‏ ‏أَبِي سُفْيَانَ ‏","","",""],[21455,21455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا بِفِنَاءِ الْمَسْجِدِ حَيْثُ تُوضَعُ الْجَنَائِزُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ بَيْنَ ظَهْرَيْنَا فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَصَرَهُ قِبَلَ السَّمَاءِ فَنَظَرَ ثُمَّ ‏ ‏طَأْطَأَ ‏ ‏بَصَرَهُ وَوَضَعَ يَدَهُ عَلَى جَبْهَتِهِ ثُمَّ قَالَ سُبْحَانَ اللَّهِ سُبْحَانَ اللَّهِ مَاذَا نَزَلَ مِنْ التَّشْدِيدِ قَالَ فَسَكَتْنَا يَوْمَنَا ‏ ‏وَلَيْلَتَنَا فَلَمْ نَرَهَا خَيْرًا حَتَّى أَصْبَحْنَا قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا التَّشْدِيدُ الَّذِي نَزَلَ قَالَ فِي الدَّيْنِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَوْ أَنَّ رَجُلًا قُتِلَ فِي سَبِيلِ اللَّهِ ثُمَّ عَاشَ ثُمَّ قُتِلَ فِي سَبِيلِ اللَّهِ ثُمَّ عَاشَ وَعَلَيْهِ دَيْنٌ مَا دَخَلَ الْجَنَّةَ حَتَّى يَقْضِيَ دَيْنَهُ ‏","","",""],[21456,21456,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏مُحَمَّدِ بْنِ جَحْشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَحْشٍ ‏ ‏خَتَنِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏مَعْمَرٍ ‏ ‏بِفِنَاءِ الْمَسْجِدِ مُحْتَبِيًا كَاشِفًا عَنْ طَرَفِ فَخِذِهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمِّرْ فَخِذَكَ يَا ‏ ‏مَعْمَرُ ‏ ‏فَإِنَّ ‏ ‏الْفَخِذَ عَوْرَةٌ ‏","","",""],[21457,21457,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَحْشٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ عَلَى ‏ ‏مَعْمَرٍ ‏ ‏وَفَخِذَاهُ مَكْشُوفَتَانِ فَقَالَ يَا ‏ ‏مَعْمَرُ ‏ ‏غَطِّ فَخِذَيْكَ فَإِنَّ ‏ ‏الْفَخِذَيْنِ عَوْرَةٌ ‏","","",""],[21458,21458,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏حَدَّثَنَا ‏ ‏سَمُرَةُ بْنُ سَهْمٍ ‏ ‏قَالَ ‏ ‏نَزَلْتُ عَلَى ‏ ‏أَبِي هَاشِمِ بْنِ عُتْبَةَ ‏ ‏وَهُوَ طَعِينٌ فَدَخَلَ عَلَيْهِ ‏ ‏مُعَاوِيَةُ ‏ ‏يَعُودُهُ فَبَكَى فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏مَا يُبْكِيكَ أَوَجَعٌ ‏ ‏يَشْتَزُّكَ ‏ ‏أَمْ عَلَى الدُّنْيَا فَقَدْ ذَهَبَ صَفْوُهَا فَقَالَ عَلَى كُلٍّ لَا وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ إِلَيَّ عَهْدًا فَوَدِدْتُ أَنِّي اتَّبَعْتُهُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَلَّكَ أَنْ تُدْرِكَ أَمْوَالًا تُقْسَمُ بَيْنَ أَقْوَامٍ وَإِنَّمَا يَكْفِيكَ مِنْ جَمْعِ الْمَالِ خَادِمٌ وَمَرْكَبٌ فِي سَبِيلِ اللَّهِ تَعَالَى فَوَجَدْتُ فَجَمَعْتُ ‏","","",""],[21459,21459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ سَيْفٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ غُطَيْفٍ ‏ ‏أَوْ ‏ ‏غُطَيْفِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ مِنْ الْأَشْيَاءِ لَمْ أَنْسَ أَنِّي ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَمِينَهُ عَلَى شِمَالِهِ فِي الصَّلَاةِ ‏","","",""],[21460,21460,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ عَبْدِ اللَّهِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏ابْنَةِ ‏ ‏أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ ‏ ‏زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلْنَا أَرْضَ ‏ ‏الْحَبَشَةِ ‏ ‏جَاوَرْنَا بِهَا خَيْرَ جَارٍ ‏ ‏النَّجَاشِيَّ ‏ ‏أَمَّنَّا عَلَى دِينِنَا وَعَبَدْنَا اللَّهَ تَعَالَى لَا نُؤْذَى وَلَا نَسْمَعُ شَيْئًا نَكْرَهُهُ فَلَمَّا بَلَغَ ذَلِكَ ‏ ‏قُرَيْشًا ‏ ‏ائْتَمَرُوا أَنْ يَبْعَثُوا إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فِينَا رَجُلَيْنِ ‏ ‏جَلْدَيْنِ ‏ ‏وَأَنْ يُهْدُوا ‏ ‏لِلنَّجَاشِيِّ ‏ ‏هَدَايَا مِمَّا ‏ ‏يُسْتَطْرَفُ ‏ ‏مِنْ مَتَاعِ ‏ ‏مَكَّةَ ‏ ‏وَكَانَ مِنْ أَعْجَبِ مَا يَأْتِيهِ مِنْهَا إِلَيْهِ ‏ ‏الْأَدَمُ ‏ ‏فَجَمَعُوا لَهُ ‏ ‏أَدَمًا ‏ ‏كَثِيرًا وَلَمْ يَتْرُكُوا مِنْ ‏ ‏بَطَارِقَتِهِ ‏ ‏بِطْرِيقًا ‏ ‏إِلَّا أَهْدَوْا لَهُ هَدِيَّةً ثُمَّ بَعَثُوا بِذَلِكَ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي رَبِيعَةَ بْنِ الْمُغِيرَةِ الْمَخْزُومِيَّ ‏ ‏وَعَمْرَو بْنَ الْعَاصِ بْنِ وَائِلٍ السَّهْمِيَّ ‏ ‏وَأَمَرُوهُمَا أَمْرَهُمْ وَقَالُوا لَهُمَا ادْفَعَا إِلَى كُلِّ بِطْرِيقٍ هَدِيَّتَهُ قَبْلَ أَنْ تُكَلِّمُوا ‏ ‏النَّجَاشِيَّ ‏ ‏فِيهِمْ ثُمَّ قَدِّمُوا ‏ ‏لِلنَّجَاشِيِّ ‏ ‏هَدَايَاهُ ثُمَّ سَلُوهُ أَنْ يُسَلِّمَهُمْ إِلَيْكُمْ قَبْلَ أَنْ يُكَلِّمَهُمْ قَالَتْ فَخَرَجَا فَقَدِمَا عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَنَحْنُ عِنْدَهُ بِخَيْرِ دَارٍ وَخَيْرِ جَارٍ فَلَمْ يَبْقَ مِنْ ‏ ‏بَطَارِقَتِهِ ‏ ‏بِطْرِيقٌ ‏ ‏إِلَّا دَفَعَا إِلَيْهِ هَدِيَّتَهُ قَبْلَ أَنْ يُكَلِّمَا ‏ ‏النَّجَاشِيَّ ‏ ‏ثُمَّ قَالَ لِكُلِّ ‏ ‏بِطْرِيقٍ ‏ ‏مِنْهُمْ إِنَّهُ قَدْ ‏ ‏صَبَا ‏ ‏إِلَى بَلَدِ الْمَلِكِ مِنَّا غِلْمَانٌ ‏ ‏سُفَهَاءُ ‏ ‏فَارَقُوا دِينَ قَوْمِهِمْ وَلَمْ يَدْخُلُوا فِي دِينِكُمْ وَجَاءُوا بِدِينٍ مُبْتَدَعٍ لَا نَعْرِفُهُ نَحْنُ وَلَا أَنْتُمْ وَقَدْ بَعَثَنَا إِلَى الْمَلِكِ فِيهِمْ أَشْرَافُ قَوْمِهِمْ ‏ ‏لِنَرُدَّهُمْ إِلَيْهِمْ فَإِذَا كَلَّمْنَا الْمَلِكَ فِيهِمْ فَأَشِيرُوا عَلَيْهِ بِأَنْ يُسَلِّمَهُمْ إِلَيْنَا وَلَا يُكَلِّمَهُمْ فَإِنَّ قَوْمَهُمْ أَعْلَى بِهِمْ عَيْنًا وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ فَقَالُوا لَهُمَا نَعَمْ ثُمَّ إِنَّهُمَا قَرَّبَا هَدَايَاهُمْ إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَقَبِلَهَا مِنْهُمَا ثُمَّ كَلَّمَاهُ فَقَالَا لَهُ أَيُّهَا الْمَلِكُ إِنَّهُ قَدْ ‏ ‏صَبَا ‏ ‏إِلَى بَلَدِكَ مِنَّا غِلْمَانٌ ‏ ‏سُفَهَاءُ ‏ ‏فَارَقُوا دِينَ قَوْمِهِمْ وَلَمْ يَدْخُلُوا فِي دِينِكَ وَجَاءُوا بِدِينٍ مُبْتَدَعٍ لَا نَعْرِفُهُ نَحْنُ وَلَا أَنْتَ وَقَدْ بَعَثَنَا إِلَيْكَ فِيهِمْ أَشْرَافُ قَوْمِهِمْ مِنْ آبَائِهِمْ وَأَعْمَامِهِمْ وَعَشَائِرِهِمْ لِتَرُدَّهُمْ إِلَيْهِمْ فَهُمْ أَعْلَى بِهِمْ ‏ ‏عَيْنًا ‏ ‏وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ وَعَاتَبُوهُمْ فِيهِ قَالَتْ وَلَمْ يَكُنْ شَيْءٌ أَبْغَضُ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ ‏ ‏وَعَمْرِو بْنِ الْعَاصِ ‏ ‏مِنْ أَنْ يَسْمَعَ ‏ ‏النَّجَاشِيُّ ‏ ‏كَلَامَهُمْ فَقَالَتْ ‏ ‏بَطَارِقَتُهُ ‏ ‏حَوْلَهُ صَدَقُوا أَيُّهَا الْمَلِكُ قَوْمُهُمْ أَعْلَى بِهِمْ ‏ ‏عَيْنًا ‏ ‏وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ فَأَسْلِمْهُمْ إِلَيْهِمَا فَلْيَرُدَّانِهِمْ إِلَى بِلَادِهِمْ وَقَوْمِهِمْ قَالَ فَغَضِبَ ‏ ‏النَّجَاشِيُّ ‏ ‏ثُمَّ قَالَ لَا ‏ ‏هَايْمُ اللَّهِ إِذًا لَا أُسْلِمَهُمْ إِلَيْهِمَا وَلَا أَكَادُ قَوْمًا جَاوَرُونِي وَنَزَلُوا بِلَادِي وَاخْتَارُونِي عَلَى مَنْ سِوَايَ حَتَّى أَدْعُوَهُمْ فَأَسْأَلَهُمْ مَا يَقُولُ هَذَانِ فِي أَمْرِهِمْ فَإِنْ كَانُوا كَمَا يَقُولَانِ أَسْلَمْتُهُمْ إِلَيْهِمَا وَرَدَدْتُهُمْ إِلَى قَوْمِهِمْ وَإِنْ كَانُوا عَلَى غَيْرِ ذَلِكَ مَنَعْتُهُمْ مِنْهُمَا وَأَحْسَنْتُ جِوَارَهُمْ مَا جَاوَرُونِي قَالَتْ ثُمَّ أَرْسَلَ إِلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَاهُمْ فَلَمَّا جَاءَهُمْ رَسُولُهُ اجْتَمَعُوا ثُمَّ قَالَ بَعْضُهُمْ لِبَعْضٍ مَا تَقُولُونَ لِلرَّجُلِ إِذَا جِئْتُمُوهُ قَالُوا نَقُولُ وَاللَّهِ مَا عَلِمْنَا وَمَا أَمَرَنَا بِهِ نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَائِنٌ فِي ذَلِكَ مَا هُوَ كَائِنٌ فَلَمَّا جَاءُوهُ وَقَدْ دَعَا ‏ ‏النَّجَاشِيُّ ‏ ‏أَسَاقِفَتَهُ ‏ ‏فَنَشَرُوا مَصَاحِفَهُمْ حَوْلَهُ لِيَسْأَلَهُمْ فَقَالَ مَا هَذَا الدِّينُ الَّذِي فَارَقْتُمْ فِيهِ قَوْمَكُمْ وَلَمْ تَدْخُلُوا فِي دِينِي وَلَا فِي دِينِ أَحَدٍ مِنْ هَذِهِ الْأُمَمِ قَالَتْ فَكَانَ الَّذِي كَلَّمَهُ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَقَالَ لَهُ أَيُّهَا الْمَلِكُ كُنَّا قَوْمًا أَهْلَ جَاهِلِيَّةٍ نَعْبُدُ الْأَصْنَامَ وَنَأْكُلُ الْمَيْتَةَ ‏ ‏وَنَأْتِي الْفَوَاحِشَ وَنَقْطَعُ الْأَرْحَامَ ‏ ‏وَنُسِيئُ الْجِوَارَ يَأْكُلُ الْقَوِيُّ مِنَّا الضَّعِيفَ فَكُنَّا عَلَى ذَلِكَ حَتَّى ‏ ‏بَعَثَ اللَّهُ إِلَيْنَا رَسُولًا مِنَّا نَعْرِفُ نَسَبَهُ وَصِدْقَهُ وَأَمَانَتَهُ وَعَفَافَهُ فَدَعَانَا إِلَى اللَّهِ تَعَالَى لِنُوَحِّدَهُ وَنَعْبُدَهُ وَنَخْلَعَ مَا كُنَّا نَعْبُدُ نَحْنُ وَآبَاؤُنَا مِنْ دُونِهِ مِنْ الْحِجَارَةِ وَالْأَوْثَانِ وَأَمَرَ بِصِدْقِ الْحَدِيثِ وَأَدَاءِ الْأَمَانَةِ وَصِلَةِ الرَّحِمِ وَحُسْنِ الْجِوَارِ وَالْكَفِّ عَنْ الْمَحَارِمِ وَالدِّمَاءِ وَنَهَانَا عَنْ الْفَوَاحِشِ وَقَوْلِ الزُّورِ وَأَكْلِ مَالِ الْيَتِيمِ وَقَذْفِ ‏ ‏الْمُحْصَنَةِ ‏ ‏وَأَمَرَنَا أَنْ نَعْبُدَ اللَّهَ وَحْدَهُ لَا نُشْرِكُ بِهِ شَيْئًا وَأَمَرَنَا بِالصَّلَاةِ وَالزَّكَاةِ وَالصِّيَامِ قَالَ فَعَدَّدَ عَلَيْهِ أُمُورَ الْإِسْلَامِ فَصَدَّقْنَاهُ وَآمَنَّا بِهِ وَاتَّبَعْنَاهُ عَلَى مَا جَاءَ بِهِ فَعَبَدْنَا اللَّهَ وَحْدَهُ فَلَمْ نُشْرِكْ بِهِ شَيْئًا وَحَرَّمْنَا مَا حَرَّمَ عَلَيْنَا وَأَحْلَلْنَا مَا أَحَلَّ لَنَا فَعَدَا عَلَيْنَا قَوْمُنَا فَعَذَّبُونَا فَفَتَنُونَا عَنْ دِينِنَا لِيَرُدُّونَا إِلَى عِبَادَةِ الْأَوْثَانِ مِنْ عِبَادَةِ اللَّهِ وَأَنْ نَسْتَحِلَّ مَا كُنَّا نَسْتَحِلُّ مِنْ الْخَبَائِثِ وَلَمَّا قَهَرُونَا وَظَلَمُونَا وَشَقُّوا عَلَيْنَا وَحَالُوا بَيْنَنَا وَبَيْنَ دِينِنَا خَرَجْنَا إِلَى بَلَدِكَ وَاخْتَرْنَاكَ عَلَى مَنْ سِوَاكَ وَرَغِبْنَا فِي جِوَارِكَ وَرَجَوْنَا أَنْ لَا نُظْلَمَ عِنْدَكَ أَيُّهَا الْمَلِكُ قَالَتْ فَقَالَ لَهُ ‏ ‏النَّجَاشِيُّ ‏ ‏هَلْ مَعَكَ مِمَّا جَاءَ بِهِ عَنْ اللَّهِ مِنْ شَيْءٍ قَالَتْ فَقَالَ لَهُ ‏ ‏جَعْفَرٌ ‏ ‏نَعَمْ فَقَالَ لَهُ ‏ ‏النَّجَاشِيُّ ‏ ‏فَاقْرَأْهُ عَلَيَّ فَقَرَأَ عَلَيْهِ صَدْرًا مِنْ ‏ ‏كهيعص ‏ ‏قَالَتْ فَبَكَى وَاللَّهِ ‏ ‏النَّجَاشِيُّ ‏ ‏حَتَّى ‏ ‏أَخْضَلَ ‏ ‏لِحْيَتَهُ وَبَكَتْ ‏ ‏أَسَاقِفَتُهُ ‏ ‏حَتَّى ‏ ‏أَخْضَلُوا ‏ ‏مَصَاحِفَهُمْ حِينَ سَمِعُوا مَا تَلَا عَلَيْهِمْ ثُمَّ قَالَ ‏ ‏النَّجَاشِيُّ ‏ ‏إِنَّ هَذَا وَالَّذِي جَاءَ بِهِ ‏ ‏مُوسَى ‏ ‏لَيَخْرُجُ مِنْ ‏ ‏مِشْكَاةٍ ‏ ‏وَاحِدَةٍ انْطَلِقَا فَوَاللَّهِ لَا أُسْلِمُهُمْ إِلَيْكُمْ أَبَدًا وَلَا أَكَادُ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَلَمَّا خَرَجَا مِنْ عِنْدِهِ قَالَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏وَاللَّهِ لَآتِيَنَّهُ غَدًا أَعِيبُهُمْ عِنْدَهُ ثُمَّ أَسْتَأْصِلُ بِهِ خَضْرَاءَهُمْ قَالَتْ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ ‏ ‏وَكَانَ أَتْقَى الرَّجُلَيْنِ فِينَا لَا تَفْعَلْ فَإِنَّ لَهُمْ أَرْحَامًا وَإِنْ كَانُوا قَدْ خَالَفُونَا قَالَ وَاللَّهِ لَأُخْبِرَنَّهُ أَنَّهُمْ يَزْعُمُونَ أَنَّ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏عَبْدٌ قَالَتْ ثُمَّ ‏ ‏غَدَا عَلَيْهِ الْغَدَ فَقَالَ لَهُ أَيُّهَا الْمَلِكُ إِنَّهُمْ يَقُولُونَ فِي ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏قَوْلًا عَظِيمًا فَأَرْسِلْ إِلَيْهِمْ فَسَلْهُمْ عَمَّا يَقُولُونَ فِيهِ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَأَرْسَلَ إِلَيْهِمْ يَسْأَلُهُمْ عَنْهُ قَالَتْ وَلَمْ يَنْزِلْ بِنَا مِثْلُهَا فَاجْتَمَعَ الْقَوْمُ فَقَالَ بَعْضُهُمْ لِبَعْضٍ مَاذَا تَقُولُونَ فِي ‏ ‏عِيسَى ‏ ‏إِذَا سَأَلَكُمْ عَنْهُ قَالُوا نَقُولُ وَاللَّهِ فِيهِ مَا قَالَ اللَّهُ سُبْحَانَهُ وَتَعَالَى وَمَا جَاءَ بِهِ نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَائِنًا فِي ذَلِكَ مَا هُوَ كَائِنٌ فَلَمَّا دَخَلُوا عَلَيْهِ قَالَ لَهُمْ مَا تَقُولُونَ فِي ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏فَقَالَ لَهُ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏نَقُولُ فِيهِ الَّذِي جَاءَ بِهِ نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ عَبْدُ اللَّهِ وَرَسُولُهُ وَرُوحُهُ وَكَلِمَتُهُ أَلْقَاهَا إِلَى ‏ ‏مَرْيَمَ ‏ ‏الْعَذْرَاءِ ‏ ‏الْبَتُولِ ‏ ‏قَالَتْ فَضَرَبَ ‏ ‏النَّجَاشِيُّ ‏ ‏يَدَهُ عَلَى الْأَرْضِ فَأَخَذَ مِنْهَا عُودًا ثُمَّ قَالَ مَا عَدَا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏مَا قُلْتَ هَذَا الْعُودَ ‏ ‏فَنَاخَرَتْ ‏ ‏بَطَارِقَتُهُ ‏ ‏حَوْلَهُ حِينَ قَالَ مَا قَالَ فَقَالَ وَإِنْ ‏ ‏نَخَرْتُمْ ‏ ‏وَاللَّهِ اذْهَبُوا فَأَنْتُمْ ‏ ‏سُيُومٌ ‏ ‏بِأَرْضِي ‏ ‏وَالسُّيُومُ ‏ ‏الْآمِنُونَ مَنْ سَبَّكُمْ ‏ ‏غَرِمَ ‏ ‏ثُمَّ مَنْ سَبَّكُمْ ‏ ‏غَرِمَ ‏ ‏ثُمَّ مَنْ سَبَّكُمْ ‏ ‏غَرِمَ ‏ ‏فَمَا أُحِبُّ أَنَّ لِي دَبْرَ ذَهَبٍ وَأَنِّي آذَيْتُ رَجُلًا مِنْكُمْ وَالدَّبْرُ بِلِسَانِ ‏ ‏الْحَبَشَةِ ‏ ‏الْجَبَلُ رُدُّوا عَلَيْهِمَا هَدَايَاهُمَا فَلَا حَاجَةَ لَنَا بِهَا فَوَاللَّهِ مَا أَخَذَ اللَّهُ مِنِّي الرِّشْوَةَ حِينَ رَدَّ عَلَيَّ مُلْكِي فَآخُذَ الرِّشْوَةَ فِيهِ وَمَا أَطَاعَ فِيَّ النَّاسَ فَأُطِيعَهُمْ فِيهِ قَالَتْ فَخَرَجَا مِنْ عِنْدِهِ مَقْبُوحَيْنِ مَرْدُودًا عَلَيْهِمَا مَا جَاءَا بِهِ وَأَقَمْنَا عِنْدَهُ بِخَيْرِ دَارٍ مَعَ خَيْرِ جَارٍ قَالَتْ فَوَاللَّهِ إِنَّا عَلَى ذَلِكَ إِذْ نَزَلَ بِهِ ‏ ‏يَعْنِي مَنْ يُنَازِعُهُ فِي مُلْكِهِ ‏ ‏قَالَتْ فَوَاللَّهِ مَا عَلِمْنَا حُزْنًا قَطُّ كَانَ أَشَدَّ مِنْ حُزْنٍ حَزِنَّاهُ عِنْدَ ذَلِكَ تَخَوُّفًا أَنْ يَظْهَرَ ذَلِكَ عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَيَأْتِيَ رَجُلٌ لَا يَعْرِفُ مِنْ حَقِّنَا مَا كَانَ ‏ ‏النَّجَاشِيُّ ‏ ‏يَعْرِفُ مِنْهُ قَالَتْ وَسَارَ ‏ ‏النَّجَاشِيُّ ‏ ‏وَبَيْنَهُمَا عُرْضُ النِّيلِ قَالَ فَقَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَجُلٌ يَخْرُجُ حَتَّى يَحْضُرَ وَقْعَةَ الْقَوْمِ ثُمَّ يَأْتِيَنَا بِالْخَبَرِ قَالَتْ فَقَالَ ‏ ‏الزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا قَالَتْ وَكَانَ مِنْ أَحْدَثِ الْقَوْمِ سِنًّا قَالَتْ فَنَفَخُوا لَهُ قِرْبَةً فَجَعَلَهَا فِي صَدْرِهِ ثُمَّ سَبَحَ عَلَيْهَا حَتَّى خَرَجَ إِلَى نَاحِيَةِ النِّيلِ الَّتِي بِهَا مُلْتَقَى الْقَوْمِ ثُمَّ انْطَلَقَ حَتَّى حَضَرَهُمْ قَالَتْ وَدَعَوْنَا اللَّهَ تَعَالَى ‏ ‏لِلنَّجَاشِيِّ ‏ ‏بِالظُّهُورِ عَلَى عَدُوِّهِ وَالتَّمْكِينِ لَهُ فِي بِلَادِهِ وَاسْتَوْثَقَ عَلَيْهِ أَمْرُ ‏ ‏الْحَبَشَةِ ‏ ‏فَكُنَّا عِنْدَهُ فِي خَيْرِ مَنْزِلٍ حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِمَكَّةَ ‏","","",""],[21461,21461,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عُرْفُطَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَالِدُ ‏ ‏إِنَّهَا سَتَكُونُ بَعْدِي أَحْدَاثٌ وَفِتَنٌ وَاخْتِلَافٌ فَإِنْ اسْتَطَعْتَ أَنْ تَكُونَ عَبْدَ اللَّهِ الْمَقْتُولَ لَا الْقَاتِلَ فَافْعَلْ ‏","","",""],[21462,21462,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَسَارٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏سُلَيْمَانَ بْنِ صُرَدٍ ‏ ‏وَخَالِدِ بْنِ عُرْفُطَةَ ‏ ‏قَالَ فَذَكَرُوا رَجُلًا مَاتَ مِنْ بَطْنِهِ قَالَ فَكَأَنَّمَا اشْتَهَيَا أَنْ يُصَلِّيَا عَلَيْهِ قَالَ فَقَالَ أَحَدُهُمَا لِلْآخَرِ أَلَمْ يَقُلْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَهُ بَطْنُهُ فَإِنَّهُ لَنْ يُعَذَّبَ فِي قَبْرِهِ قَالَ الْآخَرُ بَلَى ‏","","",""],[21463,21463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏مَوْلَى ‏ ‏خَالِدِ بْنِ عُرْفُطَةَ ‏ ‏أَنَّ ‏ ‏خَالِدَ بْنَ عُرْفُطَةَ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏يَعْنِي ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏مَوْلَى ‏ ‏خَالِدِ بْنِ عُرْفُطَةَ ‏ ‏أَنَّ ‏ ‏خَالِدَ بْنَ عُرْفُطَةَ ‏ ‏قَالَ ‏ ‏لِلْمُخْتَارِ ‏ ‏هَذَا رَجُلٌ كَذَّابٌ وَلَقَدْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ جَهَنَّمَ ‏","","",""],[21464,21464,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ سُوَيْدٍ الْحَضْرَمِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ بِأَرْضِنَا أَعْنَابًا نَعْصِرُهَا أَفَنَشْرَبُ مِنْهَا قَالَ لَا فَرَاجَعْتُهُ فَقَالَ لَا ثُمَّ رَاجَعْتُهُ فَقَالَ لَا فَقُلْتُ إِنَّا ‏ ‏نَسْتَشْفِي بِهَا لِلْمَرِيضِ قَالَ ‏ ‏إِنَّهُ لَيْسَ بِشِفَاءٍ وَلَكِنَّهُ دَاءٌ ‏","","",""],[21465,21465,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏زُهْرَةُ يَعْنِي ابْنَ مَعْبَدِ بْنِ عَبْدِ اللَّهِ بْنِ هِشَامٍ أَبُو عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ آخِذٌ بِيَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَاللَّهِ يَا رَسُولَ اللَّهِ لَأَنْتَ أَحَبُّ إِلَيَّ مِنْ كُلِّ شَيْءٍ إِلَّا نَفْسِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏حَتَّى أَكُونَ أَحَبَّ إِلَيْكَ مِنْ نَفْسِكَ قَالَ ‏ ‏عُمَرُ ‏ ‏فَأَنْتَ الْآنَ وَاللَّهِ أَحَبُّ إِلَيَّ مِنْ نَفْسِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآنَ يَا ‏ ‏عُمَرُ ‏","","",""],[21466,21466,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏زُهْرَةُ أَبُو عَقِيلٍ الْقُرَشِيُّ ‏ ‏أَنَّ جَدَّهُ ‏ ‏عَبْدَ اللَّهِ بْنَ هِشَامٍ ‏ ‏احْتَلَمَ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَكَحَ النِّسَاءَ ‏","","",""],[21467,21467,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ ‏ ‏وَاكِلْهَا ‏","","",""],[21468,21468,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْبَخْتَرِيِّ الطَّائِيَّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ يَهْلِكَ النَّاسُ حَتَّى يُعْذِرُوا مِنْ أَنْفُسِهِمْ ‏","","",""],[21469,21469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَلَا إِنَّ ‏ ‏الْعَارِيَةَ ‏ ‏مُؤَدَّاةٌ ‏ ‏وَالْمِنْحَةَ ‏ ‏مَرْدُودَةٌ وَالدَّيْنَ مَقْضِيٌّ وَالزَّعِيمَ ‏ ‏غَارِمٌ ‏","","",""],[21470,21470,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُنْذِرِ ‏ ‏مَوْلَى ‏ ‏أَبِي ذَرٍّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَيَّةَ الْمَخْزُومِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِلِصٍّ فَاعْتَرَفَ وَلَمْ يُوجَدْ مَعَهُ مَتَاعٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَخَالُكَ سَرَقْتَ قَالَ بَلَى مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْطَعُوهُ ثُمَّ جِيئُوا بِهِ قَالَ فَقَطَعُوهُ ثُمَّ جَاءُوا بِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ قَالَ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ تُبْ عَلَيْهِ ‏","","",""],[21471,21471,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جِنَازَةٍ فَلَمَّا رَجَعْنَا لَقِيَنَا دَاعِي امْرَأَةٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ فُلَانَةَ ‏ ‏تَدْعُوكَ وَمَنْ مَعَكَ إِلَى طَعَامٍ فَانْصَرَفَ فَانْصَرَفْنَا مَعَهُ فَجَلَسْنَا مَجَالِسَ الْغِلْمَانِ مِنْ آبَائِهِمْ بَيْنَ أَيْدِيهِمْ ثُمَّ جِيءَ بِالطَّعَامِ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ وَوَضَعَ الْقَوْمُ أَيْدِيَهُمْ فَفَطِنَ لَهُ الْقَوْمُ وَهُوَ يَلُوكُ لُقْمَتَهُ لَا ‏ ‏يُجِيزُهَا ‏ ‏فَرَفَعُوا أَيْدِيَهُمْ وَغَفَلُوا عَنَّا ثُمَّ ذَكَرُوا فَأَخَذُوا بِأَيْدِينَا فَجَعَلَ الرَّجُلُ يَضْرِبُ اللُّقْمَةَ بِيَدِهِ حَتَّى تَسْقُطَ ثُمَّ أَمْسَكُوا بِأَيْدِينَا يَنْظُرُونَ مَا يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَفَظَهَا ‏ ‏فَأَلْقَاهَا فَقَالَ أَجِدُ لَحْمَ شَاةٍ أُخِذَتْ بِغَيْرِ إِذْنِ أَهْلِهَا فَقَامَتْ الْمَرْأَةُ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّهُ كَانَ فِي نَفْسِي أَنْ أَجْمَعَكَ وَمَنْ مَعَكَ عَلَى طَعَامٍ فَأَرْسَلْتُ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَلَمْ أَجِدْ شَاةً تُبَاعُ وَكَانَ ‏ ‏عَامِرُ بْنُ أَبِي وَقَّاصٍ ‏ ‏ابْتَاعَ شَاةً أَمْسِ مِنْ ‏ ‏الْبَقِيعِ ‏ ‏فَأَرْسَلْتُ إِلَيْهِ أَنْ ابْتُغِيَ لِي شَاةٌ فِي ‏ ‏الْبَقِيعِ ‏ ‏فَلَمْ تُوجَدْ فَذُكِرَ لِي أَنَّكَ اشْتَرَيْتَ شَاةً فَأَرْسِلْ بِهَا إِلَيَّ فَلَمْ يَجِدْهُ الرَّسُولُ وَوَجَدَ أَهْلَهُ فَدَفَعُوهَا إِلَى رَسُولِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْعِمُوهَا الْأُسَارَى ‏","","",""],[21472,21472,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَنَا ‏ ‏السُّمَيْطُ ‏ ‏عَنْ ‏ ‏أَبِي السَّوَّارِ ‏ ‏حَدَّثَهُ ‏ ‏أَبُو السَّوَّارِ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُنَاسٌ يَتْبَعُونَهُ فَأَتْبَعْتُهُ مَعَهُمْ قَالَ فَفَجِئَنِي الْقَوْمُ يَسْعَوْنَ قَالَ ‏ ‏وَأَبْقَى الْقَوْمُ قَالَ فَأَتَى عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَرَبَنِي ضَرْبَةً إِمَّا ‏ ‏بِعَسِيبٍ ‏ ‏أَوْ ‏ ‏قَضِيبٍ ‏ ‏أَوْ سِوَاكٍ وَشَيْءٍ كَانَ مَعَهُ قَالَ فَوَاللَّهِ مَا أَوْجَعَنِي قَالَ ‏ ‏فَبِتُّ ‏ ‏بِلَيْلَةٍ قَالَ ‏ ‏أَوْ قُلْتُ ‏ ‏مَا ضَرَبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا لِشَيْءٍ عَلِمَهُ اللَّهُ فِيَّ قَالَ وَحَدَّثَتْنِي نَفْسِي أَنْ آتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصْبَحْتُ قَالَ فَنَزَلَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّكَ رَاعٍ لَا تَكْسِرَنَّ ‏ ‏قُرُونَ ‏ ‏رَعِيَّتِكَ قَالَ فَلَمَّا صَلَّيْنَا ‏ ‏الْغَدَاةَ ‏ ‏أَوْ قَالَ صَبَّحْنَا ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنَّ أُنَاسًا يَتْبَعُونِي وَإِنِّي لَا يُعْجِبُنِي أَنْ يَتْبَعُونِي اللَّهُمَّ فَمَنْ ضَرَبْتُ أَوْ سَبَبْتُ فَاجْعَلْهَا لَهُ كَفَّارَةً وَأَجْرًا ‏ ‏أَوْ قَالَ مَغْفِرَةً وَرَحْمَةً أَوْ كَمَا قَالَ ‏","","",""],[21473,21473,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هُرَيْمُ بْنُ سُفْيَانَ ‏ ‏عَنْ ‏ ‏بَيَانٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي شَهْمٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَرَّتْ بِي جَارِيَةٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأَخَذْتُ ‏ ‏بِكَشْحِهَا ‏ ‏قَالَ وَأَصْبَحَ الرَّسُولُ ‏ ‏يُبَايِعُ النَّاسَ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْتُهُ فَلَمْ يُبَايِعْنِي فَقَالَ صَاحِبُ ‏ ‏الْجُبَيْذَةِ ‏ ‏الْآنَ قَالَ قُلْتُ وَاللَّهِ لَا أَعُودُ قَالَ فَبَايَعَنِي ‏","","",""],[21474,21474,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏بَيَانِ بْنِ بِشْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي شَهْمٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا بَطَّالًا قَالَ فَمَرَّتْ بِي جَارِيَةٌ فِي بَعْضِ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏إِذْ هَوَيْتُ إِلَى ‏ ‏كَشْحِهَا ‏ ‏فَلَمَّا كَانَ الْغَدُ قَالَ فَأَتَى النَّاسُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَايِعُونَهُ فَأَتَيْتُهُ فَبَسَطْتُ يَدِي لِأُبَايِعَهُ فَقَبَضَ يَدَهُ وَقَالَ ‏ ‏أَحْسِبُكَ صَاحِبُ ‏ ‏الْجُبَيْذَةِ ‏ ‏يَعْنِي أَمَا إِنَّكَ صَاحِبُ ‏ ‏الْجُبَيْذَةِ ‏ ‏أَمْسِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ بَايِعْنِي فَوَاللَّهِ لَا أَعُودُ أَبَدًا قَالَ فَنَعَمْ إِذًا ‏","","",""],[21475,21475,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ مُخَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرَأَيْتَ إِنْ جَاءَ رَجُلٌ يُرِيدُ أَنْ يَسْرِقَنِي ‏ ‏أَوْ يَأْخُذَ مِنِّي ‏ ‏مَا تَأْمُرُنِي بِهِ قَالَ ‏ ‏تُعْظِمُ عَلَيْهِ بِاللَّهِ قَالَ فَإِنْ فَعَلْتُ فَلَمْ يَنْتَهِ قَالَ ‏ ‏تَسْتَعْدِي السُّلْطَانَ قَالَ فَإِنْ لَمْ يَكُنْ بِقُرْبِي مِنْهُمْ أَحَدٌ قَالَ تُجَاهِدُهُ ‏ ‏أَوْ تُقَاتِلُهُ ‏ ‏حَتَّى تُكْتَبَ فِي شُهَدَاءِ الْآخِرَةِ ‏ ‏أَوْ تَمْنَعَ مَالَكَ ‏","","",""],[21476,21476,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ مُخَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ فَقَالَ أَرَأَيْتَ إِنْ أَتَانِي رَجُلٌ يَأْخُذُ مَالِي قَالَ ‏ ‏تُذَكِّرُهُ بِاللَّهِ تَعَالَى قَالَ أَرَأَيْتَ إِنْ ذَكَّرْتُهُ بِاللَّهِ قَالَ فَإِنْ فَعَلْتُ فَلَمْ يَنْتَهِ قَالَ تَسْتَعِينُ عَلَيْهِ بِالسُّلْطَانِ قَالَ أَرَأَيْتَ إِنْ كَانَ السُّلْطَانُ مِنِّي نَائِيًا قَالَ تَسْتَعِينُ بِالْمُسْلِمِينَ قَالَ أَرَأَيْتَ إِنْ لَمْ يَحْضُرْنِي أَحَدٌ ‏ ‏مِنْ الْمُسْلِمِينَ وَعَجِلَ عَلَيَّ قَالَ فَقَاتِلْ حَتَّى ‏ ‏تَحْرُزَ ‏ ‏مَالَكَ ‏ ‏أَوْ تُقْتَلَ ‏ ‏فَتَكُونَ فِي شُهَدَاءِ الْآخِرَةِ ‏","","",""],[21477,21477,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُقْبَةَ ‏ ‏وَكَانَ مَوْلًى مِنْ أَهْلِ ‏ ‏فَارِسَ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَضَرَبْتُ رَجُلًا مِنْ الْمُشْرِكِينَ فَقُلْتُ خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْفَارِسِيُّ فَبَلَغَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هَلَّا قُلْتَ خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْأَنْصَارِيُّ ‏","","",""],[21478,21478,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَلَا يَرْفَعْ بَصَرَهُ إِلَى السَّمَاءِ أَنْ ‏ ‏يُلْتَمَعَ ‏ ‏بَصَرُهُ ‏","","",""],[21479,21479,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ يَعْنِي ابْنَ زَاذَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ الزِّمَّانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ ‏ ‏كَفَّارَةُ سَنَتَيْنِ وَسُئِلَ عَنْ صَوْمِ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏فَقَالَ كَفَّارَةُ سَنَةٍ ‏","","",""],[21480,21480,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ ‏ ‏جَلِيسٍ كَانَ ‏ ‏لِأَبِي قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَقَامَ ‏ ‏الْبَيِّنَةَ ‏ ‏عَلَى قَتِيلٍ فَلَهُ ‏ ‏سَلَبُهُ ‏","","",""],[21481,21481,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ أَبُو إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي عَتَّابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي يَحْمِلُ ‏ ‏أُمَامَةَ ‏ ‏أَوْ ‏ ‏أُمَيْمَةَ بِنْتَ أَبِي الْعَاصِ ‏ ‏وَهِيَ بِنْتُ ‏ ‏زَيْنَبَ ‏ ‏يَحْمِلُهَا إِذَا قَامَ وَيَضَعُهَا إِذَا رَكَعَ حَتَّى فَرَغَ ‏","","",""],[21482,21482,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّنَا يَقْرَأُ بِنَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَيُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَكَانَ يَفْعَلُ ذَلِكَ فِي صَلَاةِ الصُّبْحِ يُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَكَانَ يَقْرَأُ بِنَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الْعَصْرِ ‏","","",""],[21483,21483,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُخْلَطَ شَيْءٌ مِنْهُ بِشَيْءٍ وَلَكِنْ لِيُنْتَبَذْ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَةٍ ‏","","",""],[21484,21484,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَنَفَّسَ فِي الْإِنَاءِ أَوْ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ ‏ ‏أَوْ ‏ ‏يَسْتَطِيبَ ‏ ‏بِيَمِينِهِ ‏","","",""],[21485,21485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ ‏","","",""],[21486,21486,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَهُوَ حَامِلٌ ‏ ‏أُمَامَةَ بِنْتَ زَيْنَبَ ‏ ‏فَإِذَا رَكَعَ وَسَجَدَ وَضَعَهَا وَإِذَا قَامَ حَمَلَهَا ‏","","",""],[21487,21487,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَرَى الرُّؤْيَا ‏ ‏أُعْرَى ‏ ‏مِنْهَا غَيْرَ أَنِّي لَا ‏ ‏أُزَمَّلُ ‏ ‏حَتَّى لَقِيتُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَحَدَّثَنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا مِنْ اللَّهِ وَالْحُلْمُ مِنْ الشَّيْطَانِ فَمَنْ رَأَى رُؤْيَا يَكْرَهُهَا فَلَا يُخْبِرْ بِهَا وَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا وَلْيَسْتَعِذْ بِاللَّهِ مِنْ شَرِّهَا فَإِنَّهَا لَا تَضُرُّهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أُخْرَى فَإِنَّهُ لَنْ يَرَى شَيْئًا يَكْرَهُهُ ‏","","",""],[21488,21488,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي مُحَمَّدٍ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَصَابَ حِمَارَ وَحْشٍ ‏ ‏يَعْنِي وَهُوَ ‏ ‏مُحِلٌّ ‏ ‏وَهُمْ مُحْرِمُونَ فَسَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهِ ‏","","",""],[21489,21489,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ ‏ ‏جَلِيسُ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏بَارَزْتُ رَجُلًا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَنَفَّلَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَبَهُ ‏","","",""],[21490,21490,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏حَدَّثَتْنِي ‏ ‏امْرَأَةُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏كَانَ ‏ ‏يُصْغِي ‏ ‏الْإِنَاءَ لِلْهِرِّ فَيَشْرَبُ ‏ ‏وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّهَا مِنْ الطَّوَّافِينَ ‏ ‏وَالطَّوَّافَاتِ ‏ ‏عَلَيْكُمْ ‏","","",""],[21491,21491,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏وَابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيُصَلِّ رَكْعَتَيْنِ مِنْ قَبْلِ أَنْ يَجْلِسَ ‏","","",""],[21492,21492,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْنَاهُ مِنْ ‏ ‏دَاوُدَ بْنِ شَابُورَ ‏ ‏عَنْ ‏ ‏أَبِي قَزْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏أَبِي حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏صِيَامُ ‏ ‏عَرَفَةَ ‏ ‏يُكَفِّرُ السَّنَةَ وَالَّتِي تَلِيهَا وَصِيَامُ ‏ ‏عَاشُورَاءَ ‏ ‏يُكَفِّرُ سَنَةً ‏ ‏لَمْ يَرْفَعْهُ لَنَا ‏ ‏سُفْيَانُ ‏ ‏وَهُوَ مَرْفُوعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏فَقَالَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21493,21493,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏وَابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّ النَّاسَ ‏ ‏وَأُمَامَةُ بِنْتُ أَبِي الْعَاصِ ‏ ‏يَعْنِي حَامِلُهَا ‏ ‏فَإِذَا رَكَعَ وَضَعَهَا وَإِذَا فَرَغَ مِنْ السُّجُودِ رَفَعَهَا ‏","","",""],[21494,21494,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21495,21495,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ وَإِذَا أَتَى الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَإِذَا تَمَسَّحَ فَلَا يَتَمَسَّحَنَّ بِيَمِينِهِ ‏","","",""],[21496,21496,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَوْمُ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏يُكَفِّرُ سَنَتَيْنِ مَاضِيَةً وَمُسْتَقْبَلَةً وَصَوْمُ ‏ ‏عَاشُورَاءَ ‏ ‏يُكَفِّرُ سَنَةً مَاضِيَةً ‏","","",""],[21497,21497,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنِ ‏ ‏ابْنٍ لِكَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ ‏ ‏قَالَ ‏ ‏مُرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ قَالَ ‏ ‏مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ قَالُوا يَا رَسُولَ اللَّهِ مَا الْمُسْتَرِيحُ وَالْمُسْتَرَاحُ مِنْهُ قَالَ الْمُؤْمِنُ اسْتَرَاحَ مِنْ ‏ ‏نَصَبِ ‏ ‏الدُّنْيَا وَأَذَاهَا إِلَى رَحْمَةِ اللَّهِ تَعَالَى وَالْفَاجِرُ اسْتَرَاحَ مِنْهُ الْعِبَادُ وَالْبِلَادُ وَالشَّجَرُ وَالدَّوَابُّ ‏","","",""],[21498,21498,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ الزِّمَّانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ ‏ ‏لِغَيْلَانَ ‏ ‏الْأَنْصَارِيِّ فَقَالَ بِرَأْسِهِ أَيْ نَعَمْ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِهِ فَغَضِبَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيتُ ‏ ‏أَوْ قَالَ رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا قَالَ وَلَا أَعْلَمُهُ إِلَّا قَدْ قَالَ ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا ‏ ‏وَبِبَيْعَتِنَا بَيْعَةً قَالَ فَقَامَ ‏ ‏عُمَرُ ‏ ‏أَوْ رَجُلٌ آخَرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ رَجُلٌ صَامَ الْأَبَدَ قَالَ ‏ ‏لَا صَامَ وَلَا أَفْطَرَ ‏ ‏أَوْ مَا صَامَ وَمَا أَفْطَرَ ‏ ‏قَالَ صَوْمُ يَوْمَيْنِ وَإِفْطَارُ يَوْمٍ قَالَ وَمَنْ يُطِيقُ ذَلِكَ قَالَ إِفْطَارُ يَوْمَيْنِ وَصَوْمُ يَوْمٍ قَالَ لَيْتَ اللَّهَ عَزَّ وَجَلَّ قَوَّانَا لِذَلِكَ قَالَ صَوْمُ يَوْمٍ وَإِفْطَارُ يَوْمٍ قَالَ ذَاكَ صَوْمُ أَخِي ‏ ‏دَاوُدَ ‏ ‏قَالَ صَوْمُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ قَالَ ذَاكَ يَوْمٌ وُلِدْتُ فِيهِ وَأُنْزِلَ عَلَيَّ فِيهِ قَالَ صَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَمَضَانَ إِلَى رَمَضَانَ صَوْمُ الدَّهْرِ وَإِفْطَارُهُ قَالَ صَوْمُ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏قَالَ يُكَفِّرُ السَّنَةَ الْمَاضِيَةَ وَالْبَاقِيَةَ قَالَ صَوْمُ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏قَالَ يُكَفِّرُ السَّنَةَ الْمَاضِيَةَ ‏","","",""],[21499,21499,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ ابْنُ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنٌ لِكَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ يَا أَيُّهَا النَّاسُ ‏ ‏إِيَّاكُمْ وَكَثْرَةَ الْحَدِيثِ عَنِّي مَنْ قَالَ عَلَيَّ فَلَا يَقُولَنَّ إِلَّا حَقًّا ‏ ‏أَوْ صِدْقًا ‏ ‏فَمَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[21500,21500,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْمِعُنَا الْآيَةَ فِي الظُّهْرِ وَالْعَصْرِ أَحْيَانًا ‏","","",""],[21501,21501,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏عَنْ ‏ ‏عَامِرٍ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ يَمِينَهُ عَلَى فَخِذِهِ الْيُمْنَى وَأَشَارَ بِإِصْبَعِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ الزِّمَّانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّ أَعْرَابِيًّا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِهِ فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ صَوْمُ ‏ ‏الِاثْنَيْنِ قَالَ ذَاكَ يَوْمٌ وُلِدْتُ فِيهِ وَأُنْزِلَ عَلَيَّ فِيهِ ‏","","",""],[21502,21502,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ بِهِ خَطَايَايَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ بِهِ خَطَايَاكَ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبِثَ مَا شَاءَ اللَّهُ ثُمَّ سَأَلَهُ الرَّجُلُ فَقَالَ يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ عَنِّي خَطَايَايَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ عَنْكَ خَطَايَاكَ إِلَّا الدَّيْنَ كَذَلِكَ قَالَ لِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[21503,21503,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ لِيُصَلِّيَ عَلَيْهَا فَقَالَ ‏ ‏أَعَلَيْهِ دَيْنٌ قَالُوا نَعَمْ دِينَارَانِ قَالَ أَتَرَكَ لَهُمَا وَفَاءً قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ قَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏هُمَا عَلَيَّ يَا رَسُولَ اللَّهِ فَصَلَّى عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21504,21504,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِيَّاكُمْ وَكَثْرَةَ الْحَلِفِ فِي الْبَيْعِ فَإِنَّهُ يُنَفِّقُ ثُمَّ ‏ ‏يَمْحَقُ ‏","","",""],[21505,21505,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مَعْبَدُ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا قَتَادَةَ السَّلَمِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِيَّاكُمْ وَكَثْرَةَ الْحَلِفِ فِي الْبَيْعِ فَإِنَّهُ يُنَفِّقُ ثُمَّ ‏ ‏يَمْحَقُ ‏","","",""],[21506,21506,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَقَالَ إِنَّكُمْ ‏ ‏إِنْ لَا تُدْرِكُوا الْمَاءَ غَدًا تَعْطَشُوا وَانْطَلَقَ ‏ ‏سَرَعَانُ ‏ ‏النَّاسِ يُرِيدُونَ الْمَاءَ وَلَزِمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَالَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحِلَتُهُ فَنَعَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَمْتُهُ ‏ ‏فَأَدْعَمَ ‏ ‏ثُمَّ مَالَ ‏ ‏فَدَعَمْتُهُ ‏ ‏فَأَدْعَمَ ‏ ‏ثُمَّ مَالَ حَتَّى كَادَ أَنْ ‏ ‏يَنْجَفِلَ ‏ ‏عَنْ رَاحِلَتِهِ ‏ ‏فَدَعَمْتُهُ ‏ ‏فَانْتَبَهَ فَقَالَ مَنْ الرَّجُلُ قُلْتُ ‏ ‏أَبُو قَتَادَةَ ‏ ‏قَالَ مُذْ كَمْ كَانَ مَسِيرُكَ قُلْتُ مُنْذُ اللَّيْلَةِ قَالَ حَفِظَكَ اللَّهُ كَمَا حَفِظْتَ رَسُولَهُ ثُمَّ قَالَ لَوْ ‏ ‏عَرَّسْنَا ‏ ‏فَمَالَ إِلَى شَجَرَةٍ فَنَزَلَ فَقَالَ انْظُرْ هَلْ ‏ ‏تَرَى أَحَدًا قُلْتُ هَذَا رَاكِبٌ هَذَانِ رَاكِبَانِ حَتَّى بَلَغَ سَبْعَةً فَقَالَ احْفَظُوا عَلَيْنَا صَلَاتَنَا فَنِمْنَا فَمَا أَيْقَظَنَا إِلَّا حَرُّ الشَّمْسِ فَانْتَبَهْنَا فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَارَ وَسِرْنَا ‏ ‏هُنَيْهَةً ‏ ‏ثُمَّ نَزَلَ فَقَالَ أَمَعَكُمْ مَاءٌ قَالَ قُلْتُ نَعَمْ مَعِي ‏ ‏مِيضَأَةٌ ‏ ‏فِيهَا شَيْءٌ مِنْ مَاءٍ قَالَ ائْتِ بِهَا فَأَتَيْتُهُ بِهَا فَقَالَ مَسُّوا مِنْهَا مَسُّوا مِنْهَا فَتَوَضَّأَ الْقَوْمُ وَبَقِيَتْ جَرْعَةٌ فَقَالَ ازْدَهِرْ بِهَا يَا ‏ ‏أَبَا قَتَادَةَ ‏ ‏فَإِنَّهُ سَيَكُونُ لَهَا نَبَأٌ ثُمَّ أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏وَصَلَّوْا الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ ثُمَّ صَلَّوْا الْفَجْرَ ثُمَّ رَكِبَ وَرَكِبْنَا فَقَالَ بَعْضُهُمْ لِبَعْضٍ ‏ ‏فَرَّطْنَا ‏ ‏فِي صَلَاتِنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَقُولُونَ إِنْ كَانَ أَمْرَ دُنْيَاكُمْ فَشَأْنُكُمْ وَإِنْ كَانَ أَمْرَ دِينِكُمْ فَإِلَيَّ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏فَرَّطْنَا ‏ ‏فِي صَلَاتِنَا فَقَالَ لَا ‏ ‏تَفْرِيطَ ‏ ‏فِي النَّوْمِ إِنَّمَا ‏ ‏التَّفْرِيطُ ‏ ‏فِي الْيَقَظَةِ فَإِذَا كَانَ ذَلِكَ فَصَلُّوهَا وَمِنْ الْغَدِ وَقْتَهَا ثُمَّ قَالَ ظُنُّوا بِالْقَوْمِ قَالُوا إِنَّكَ قُلْتَ بِالْأَمْسِ إِنْ لَا تُدْرِكُوا الْمَاءَ غَدًا تَعْطَشُوا فَالنَّاسُ بِالْمَاءِ فَقَالَ أَصْبَحَ النَّاسُ وَقَدْ فَقَدُوا نَبِيَّهُمْ فَقَالَ بَعْضُهُمْ لِبَعْضٍ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَاءِ وَفِي الْقَوْمِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَقَالَا أَيُّهَا النَّاسُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ لِيَسْبِقَكُمْ إِلَى الْمَاءِ وَيُخَلِّفَكُمْ وَإِنْ يُطِعْ النَّاسُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَرْشُدُوا قَالَهَا ثَلَاثًا فَلَمَّا اشْتَدَّتْ الظَّهِيرَةُ رَفَعَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ هَلَكْنَا عَطَشًا تَقَطَّعَتْ الْأَعْنَاقُ فَقَالَ لَا ‏ ‏هُلْكَ عَلَيْكُمْ ثُمَّ قَالَ يَا ‏ ‏أَبَا قَتَادَةَ ‏ ‏ائْتِ ‏ ‏بِالْمِيضَأَةِ ‏ ‏فَأَتَيْتُهُ بِهَا فَقَالَ احْلِلْ لِي ‏ ‏غُمَرِي ‏ ‏يَعْنِي قَدَحَهُ ‏ ‏فَحَلَلْتُهُ فَأَتَيْتُهُ بِهِ فَجَعَلَ يَصُبُّ فِيهِ ‏ ‏وَيَسْقِي النَّاسَ فَازْدَحَمَ النَّاسُ عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَيُّهَا النَّاسُ أَحْسِنُوا الْمَلَأَ فَكُلُّكُمْ سَيَصْدُرُ عَنْ ‏ ‏رِيٍّ ‏ ‏فَشَرِبَ الْقَوْمُ حَتَّى لَمْ يَبْقَ غَيْرِي وَغَيْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَبَّ لِي فَقَالَ اشْرَبْ يَا ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَالَ قُلْتُ اشْرَبْ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ إِنَّ سَاقِيَ الْقَوْمِ آخِرُهُمْ فَشَرِبْتُ وَشَرِبَ بَعْدِي وَبَقِيَ فِي ‏ ‏الْمِيضَأَةِ ‏ ‏نَحْوٌ مِمَّا كَانَ فِيهَا وَهُمْ يَوْمَئِذٍ ثَلَاثُ مِائَةٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَسَمِعَنِي ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏وَأَنَا أُحَدِّثُ هَذَا الْحَدِيثَ فِي الْمَسْجِدِ الْجَامِعِ فَقَالَ مَنْ الرَّجُلُ قُلْتُ أَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَبَاحٍ الْأَنْصَارِيُّ ‏ ‏قَالَ الْقَوْمُ أَعْلَمُ بِحَدِيثِهِمْ انْظُرْ كَيْفَ تُحَدِّثُ فَإِنِّي أَحَدُ السَّبْعَةِ تِلْكَ اللَّيْلَةَ فَلَمَّا فَرَغْتُ قَالَ مَا كُنْتُ أَحْسِبُ أَنَّ أَحَدًا يَحْفَظُ هَذَا الْحَدِيثَ غَيْرِي ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَحَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ وَزَادَ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏عَرَّسَ ‏ ‏وَعَلَيْهِ لَيْلٌ تَوَسَّدَ يَمِينَهُ وَإِذَا ‏ ‏عَرَّسَ ‏ ‏الصُّبْحَ وَضَعَ رَأْسَهُ عَلَى كَفِّهِ الْيُمْنَى وَأَقَامَ سَاعِدَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[21507,21507,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَلَى ظَهْرِ بَيْتِنَا فَرَأَى كَوْكَبًا ‏ ‏انْقَضَّ ‏ ‏فَنَظَرُوا إِلَيْهِ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏إِنَّا قَدْ ‏ ‏نُهِينَا أَنْ نُتْبِعَهُ أَبْصَارَنَا ‏","","",""],[21508,21508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏الِاثْنَيْنِ فَقَالَ ‏ ‏فِيهِ وُلِدْتُ وَفِيهِ أُنْزِلَ عَلَيَّ ‏","","",""],[21509,21509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سُمَيْرٍ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَبَاحٍ ‏ ‏فَوَجَدْتُهُ قَدْ اجْتَمَعَ إِلَيْهِ نَاسٌ مِنْ النَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو قَتَادَةَ فَارِسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشَ الْأُمَرَاءِ وَقَالَ ‏ ‏عَلَيْكُمْ ‏ ‏زَيْدُ بْنُ حَارِثَةَ ‏ ‏فَإِنْ أُصِيبَ ‏ ‏زَيْدٌ ‏ ‏فجَعْفَرٌ ‏ ‏فَإِنْ أُصِيبَ ‏ ‏جَعْفَرٌ ‏ ‏فعَبْدُ اللَّهِ بْنُ رَوَاحَةَ الْأَنْصَارِيُّ ‏ ‏فَوَثَبَ ‏ ‏جَعْفَرٌ ‏ ‏فَقَالَ بِأَبِي أَنْتَ يَا نَبِيَّ اللَّهِ وَأُمِّي مَا كُنْتُ أَرْهَبُ أَنْ تَسْتَعْمِلَ عَلَيَّ ‏ ‏زَيْدًا ‏ ‏قَالَ امْضُوا فَإِنَّكَ لَا تَدْرِي أَيُّ ذَلِكَ خَيْرٌ قَالَ فَانْطَلَقَ الْجَيْشُ فَلَبِثُوا مَا شَاءَ اللَّهُ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَعِدَ الْمِنْبَرَ وَأَمَرَ أَنْ يُنَادَى الصَّلَاةُ جَامِعَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَابَ خَيْرٌ ‏ ‏أَوْ ‏ ‏ثَابَ ‏ ‏خَيْرٌ شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَلَا أُخْبِرُكُمْ عَنْ جَيْشِكُمْ هَذَا ‏ ‏الْغَازِي ‏ ‏إِنَّهُمْ انْطَلَقُوا حَتَّى لَقُوا الْعَدُوَّ فَأُصِيبَ ‏ ‏زَيْدٌ ‏ ‏شَهِيدًا فَاسْتَغْفِرُوا لَهُ فَاسْتَغْفَرَ لَهُ النَّاسُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَشَدَّ عَلَى الْقَوْمِ حَتَّى قُتِلَ شَهِيدًا أَشْهَدُ لَهُ بِالشَّهَادَةِ فَاسْتَغْفِرُوا لَهُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأَثْبَتَ قَدَمَيْهِ حَتَّى أُصِيبَ شَهِيدًا فَاسْتَغْفِرُوا لَهُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَلَمْ يَكُنْ مِنْ الْأُمَرَاءِ هُوَ أَمَّرَ نَفْسَهُ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُصْبُعَيْهِ وَقَالَ اللَّهُمَّ هُوَ سَيْفٌ مِنْ سُيُوفِكَ فَانْصُرْهُ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مَرَّةً فَانْتَصِرْ بِهِ ‏ ‏فَيَوْمَئِذٍ سُمِّيَ ‏ ‏خَالِدٌ ‏ ‏سَيْفَ اللَّهِ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْفِرُوا فَأَمِدُّوا إِخْوَانَكُمْ وَلَا يَتَخَلَّفَنَّ أَحَدٌ فَنَفَرَ النَّاسُ فِي حَرٍّ شَدِيدٍ مُشَاةً وَرُكْبَانًا ‏","","",""],[21510,21510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ يَعْنِي ابْنَ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الدَّهْرَ فَإِنَّ اللَّهَ هُوَ الدَّهْرُ ‏","","",""],[21511,21511,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِي ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الصَّخْرِ حُمَيْدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏يَحْيَى بْنَ النَّضْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُ ‏ ‏حَضَرَ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عَمْرُو بْنُ الْجَمُوحِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ قَاتَلْتُ فِي سَبِيلِ اللَّهِ حَتَّى أُقْتَلَ أَمْشِي بِرِجْلِي هَذِهِ صَحِيحَةً فِي الْجَنَّةِ ‏ ‏وَكَانَتْ رِجْلُهُ عَرْجَاءَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَقُتِلُوا يَوْمَ ‏ ‏أُحُدٍ ‏ ‏هُوَ وَابْنُ أَخِيهِ ‏ ‏وَمَوْلًى ‏ ‏لَهُمْ فَمَرَّ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْكَ تَمْشِي بِرِجْلِكَ هَذِهِ صَحِيحَةً فِي الْجَنَّةِ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهِمَا ‏ ‏وَبِمَوْلَاهُمَا ‏ ‏فَجُعِلُوا فِي قَبْرٍ وَاحِدٍ ‏","","",""],[21512,21512,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى مَيِّتٍ فَسَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَزَادَ فِيهِ ‏ ‏أَبُو سَلَمَةَ ‏ ‏اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ ‏","","",""],[21513,21513,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دُعِيَ لِجِنَازَةٍ سَأَلَ عَنْهَا فَإِنْ أُثْنِيَ عَلَيْهَا خَيْرٌ قَامَ فَصَلَّى عَلَيْهَا وَإِنْ أُثْنِيَ عَلَيْهَا غَيْرُ ذَلِكَ قَالَ لِأَهْلِهَا ‏ ‏شَأْنُكُمْ بِهَا وَلَمْ يُصَلِّ عَلَيْهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[21514,21514,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَعَدَ عَلَى فِرَاشِ ‏ ‏مُغِيبَةٍ ‏ ‏قَيَّضَ ‏ ‏اللَّهُ لَهُ يَوْمَ الْقِيَامَةِ ثُعْبَانًا ‏","","",""],[21515,21515,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَسِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ الْجُمُعَةَ ثَلَاثَ مِرَارٍ مِنْ غَيْرِ ضَرُورَةٍ طُبِعَ عَلَى قَلْبِهِ ‏","","",""],[21516,21516,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَفَّسَ عَنْ ‏ ‏غَرِيمِهِ ‏ ‏أَوْ مَحَا عَنْهُ ‏ ‏كَانَ فِي ظِلِّ الْعَرْشِ يَوْمَ الْقِيَامَةِ ‏","","",""],[21517,21517,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبُولُ مُسْتَقْبِلَ الْقِبْلَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ الطَّبَّاعِ ‏ ‏مِثْلَهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو قَتَادَةَ ‏","","",""],[21518,21518,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ الْخَيْلِ ‏ ‏الْأَدْهَمُ ‏ ‏الْأَقْرَحُ ‏ ‏الْأَرْثَمُ ‏ ‏مُحَجَّلُ ‏ ‏الثَّلَاثِ مُطْلَقُ الْيَمِينِ فَإِنْ لَمْ يَكُنْ ‏ ‏أَدْهَمَ ‏ ‏فَكُمَيْتٌ ‏ ‏عَلَى هَذِهِ ‏ ‏الشِّيَةِ ‏","","",""],[21519,21519,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَعَدَ عَلَى فِرَاشِ ‏ ‏مُغِيبَةٍ ‏ ‏بُعِثَ لَهُ يَوْمَ الْقِيَامَةِ ثُعْبَانٌ ‏","","",""],[21520,21520,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِنَا فَيَقْرَأُ فِي الْعَصْرِ وَالظُّهْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ بِسُورَتَيْنِ ‏ ‏وَأُمِّ الْكِتَابِ ‏ ‏وَكَانَ يُسْمِعُنَا الْأَحْيَانَ الْآيَةَ وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الْأَخِيرَتَيْنِ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَكَانَ يُطِيلُ أَوَّلَ رَكْعَةٍ مِنْ صَلَاةِ الْفَجْرِ وَأَوَّلَ رَكْعَةٍ مِنْ صَلَاةِ الظُّهْرِ ‏","","",""],[21521,21521,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏وَمُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرُّؤْيَا الصَّالِحَةَ مِنْ اللَّهِ وَالْحُلْمَ مِنْ الشَّيْطَانِ فَإِذَا حَلَمَ أَحَدُكُمْ حُلْمًا يَخَافُهُ فَلْيَبْصُقْ عَنْ شِمَالِهِ ثَلَاثَ مَرَّاتٍ وَلْيَتَعَوَّذْ بِاللَّهِ مِنْ الشَّيْطَانِ فَإِنَّهُ لَا يَضُرُّهُ ‏","","",""],[21522,21522,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا بَالَ أَحَدُكُمْ فَلَا يَمَسُّ ذَكَرَهُ بِيَمِينِهِ وَلَا ‏ ‏يَسْتَنْجِي ‏ ‏بِيَمِينِهِ وَلَا يَتَنَفَّسُ فِي الْإِنَاءِ ‏","","",""],[21523,21523,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سُمَيْرٍ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَبَاحٍ الْأَنْصَارِيُّ ‏ ‏وَكَانَتْ ‏ ‏الْأَنْصَارُ ‏ ‏تُفَقِّهُهُ فَأَتَيْتُهُ وَهُوَ فِي ‏ ‏حِوَاءِ ‏ ‏شَرِيكِ بْنِ الْأَعْوَرِ ‏ ‏الشَّارِعِ عَلَى الْمِرْبَدِ وَقَدْ اجْتَمَعَ عَلَيْهِ نَاسٌ مِنْ النَّاسِ فَقَالَ حَدَّثَنَا ‏ ‏أَبُو قَتَادَةَ الْأَنْصَارِيُّ فَارِسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشَ الْأُمَرَاءِ فَقَالَ ‏ ‏عَلَيْكُمْ ‏ ‏زَيْدُ بْنُ حَارِثَةَ ‏ ‏فَإِنْ أُصِيبَ ‏ ‏زَيْدٌ ‏ ‏فَجَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَإِنْ أُصِيبَ ‏ ‏جَعْفَرٌ ‏ ‏فعَبْدُ اللَّهِ بْنُ رَوَاحَةَ الْأَنْصَارِيُّ ‏ ‏فَوَثَبَ ‏ ‏جَعْفَرٌ ‏ ‏فَقَالَ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ مَا كُنْتُ أَرْهَبُ أَنْ تَسْتَعْمِلَ عَلَيَّ ‏ ‏زَيْدًا ‏ ‏قَالَ ‏ ‏امْضِهْ فَإِنَّكَ لَا تَدْرِي أَيُّ ذَلِكَ خَيْرٌ فَانْطَلَقُوا فَلَبِثُوا مَا شَاءَ اللَّهُ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَعِدَ الْمِنْبَرَ وَأَمَرَ أَنْ يُنَادَى الصَّلَاةُ جَامِعَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَابَ خَيْرٌ ‏ ‏أَوْ بَاتَ خَيْرٌ ‏ ‏أَوْ ثَابَ خَيْرٌ شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَلَا أُخْبِرُكُمْ عَنْ جَيْشِكُمْ هَذَا ‏ ‏الْغَازِي ‏ ‏إِنَّهُمْ انْطَلَقُوا فَلَقَوْا الْعَدُوَّ فَأُصِيبَ ‏ ‏زَيْدٌ ‏ ‏شَهِيدًا فَاسْتَغْفِرُوا لَهُ فَاسْتَغْفَرَ لَهُ النَّاسُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَشَدَّ عَلَى الْقَوْمِ حَتَّى قُتِلَ شَهِيدًا أَشْهَدُ لَهُ بِالشَّهَادَةِ فَاسْتَغْفِرُوا لَهُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأَثْبَتَ قَدَمَيْهِ حَتَّى قُتِلَ شَهِيدًا فَاسْتَغْفِرُوا لَهُ ثُمَّ أَخَذَ اللِّوَاءَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَلَمْ يَكُنْ مِنْ الْأُمَرَاءِ هُوَ أَمَّرَ نَفْسَهُ ثُمَّ رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِصْبَعَيْهِ فَقَالَ اللَّهُمَّ هُوَ سَيْفٌ مِنْ سُيُوفِكَ فَانْصُرْهُ فَمِنْ يَوْمِئِذٍ سُمِّيَ ‏ ‏خَالِدٌ ‏ ‏سَيْفَ اللَّهِ ثُمَّ قَالَ انْفِرُوا فَأَمِدُّوا إِخْوَانَكُمْ وَلَا يَتَخَلَّفَنَّ أَحَدٌ قَالَ فَنَفَرَ النَّاسُ فِي حَرٍّ شَدِيدٍ مُشَاةً وَرُكْبَانًا ‏","","",""],[21524,21524,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ بِبَعْضِ طُرُقِ ‏ ‏مَكَّةَ ‏ ‏تَخَلَّفَ مَعَ أَصْحَابٍ لَهُ مُحْرِمِينَ وَهُوَ غَيْرُ مُحْرِمٍ فَرَأَى حِمَارًا وَحْشِيًّا فَاسْتَوَى عَلَى فَرَسِهِ وَسَأَلَ أَصْحَابَهُ أَنْ يُنَاوِلُوهُ سَوْطَهُ فَأَبَوْا فَسَأَلَهُمْ رُمْحَهُ فَأَبَوْا وَأَخَذَهُ ثُمَّ شَدَّ عَلَى الْحِمَارِ فَقَتَلَهُ فَأَكَلَ بَعْضُ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَى بَعْضُهُمْ فَلَمَّا أَدْرَكُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلُوهُ عَنْ ذَلِكَ فَقَالَ ‏ ‏إِنَّمَا هِيَ طُعْمَةٌ أَطْعَمَكُمُوهَا اللَّهُ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏فِي الْحِمَارِ الْوَحْشِيِّ مِثْلَ ذَلِكَ إِلَّا أَنَّ فِي حَدِيثِ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَلْ مَعَكَ مِنْ لَحْمِهِ شَيْءٌ ‏","","",""],[21525,21525,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏أَحْرَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَلَمْ يُحْرِمْ ‏ ‏أَبُو قَتَادَةَ ‏ ‏قَالَ وَحُدِّثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ عَدُوًّا ‏ ‏بِفِيقَةَ ‏ ‏فَانْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَيْنَمَا أَنَا مَعَ أَصْحَابِي فَضَحِكَ بَعْضُهُمْ إِلَى بَعْضٍ فَنَظَرْتُ فَإِذَا أَنَا بِحِمَارِ وَحْشٍ فَاسْتَعَنْتُهُمْ فَأَبَوْا أَنْ يُعِينُونِي فَحَمَلْتُ عَلَيْهِ فَأَثْبَتُّهُ فَأَكَلْنَا مِنْ لَحْمِهِ وَخَشِينَا أَنْ نُقْتَطَعَ فَانْطَلَقْتُ أَطْلُبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلْتُ أَرْفَعُ فَرَسِي ‏ ‏شَأْوًا ‏ ‏وَأَسِيرُ ‏ ‏شَأْوًا ‏ ‏وَلَقِيتُ رَجُلًا مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏فِي جَوْفِ اللَّيْلِ فَقُلْتُ أَيْنَ تَرَكْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَرَكْتُهُ وَهُوَ ‏ ‏بِتِعْهِنَ ‏ ‏وَهُوَ مِمَّا ‏ ‏يَلِي ‏ ‏السُّقْيَا فَأَدْرَكْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَصْحَابَكَ يُقْرِئُونَكَ السَّلَامَ وَرَحْمَةَ اللَّهِ وَقَدْ خَشُوا أَنْ يُقْتَطَعُوا دُونَكَ فَانْتَظِرْهُمْ قَالَ فَانْتَظَرَهُمْ قُلْتُ ‏ ‏وَقَدْ أَصَبْتُ حِمَارَ وَحْشٍ وَعِنْدِي مِنْهُ فَاضِلَةٌ فَقَالَ لِلْقَوْمِ كُلُوا وَهُمْ مُحْرِمُونَ ‏","","",""],[21526,21526,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِنَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَيُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَكَانَ يَفْعَلُ ذَلِكَ فِي صَلَاةِ الصُّبْحِ يُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَكَانَ يَقْرَأُ بِنَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الْعَصْرِ ‏","","",""],[21527,21527,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مَعْبَدُ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَكَثْرَةَ الْحَلِفِ فِي الْبَيْعِ فَإِنَّهُ يُنَفِّقُ ثُمَّ ‏ ‏يَمْحَقُ ‏","","",""],[21528,21528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لِيُصَلِّيَ عَلَيْهِ فَقَالَ ‏ ‏صَلُّوا عَلَى صَاحِبِكُمْ فَإِنَّ عَلَيْهِ دَيْنًا قَالَ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏هُوَ عَلَيَّ يَا رَسُولَ اللَّهِ قَالَ بِالْوَفَاءِ قَالَ بِالْوَفَاءِ قَالَ فَصَلَّى عَلَيْهِ وَإِنَّمَا كَانَ عَلَيْهِ ثَمَانِيَةَ عَشَرَ ‏ ‏أَوْ تِسْعَةَ عَشَرَ ‏ ‏دِرْهَمًا ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عُثْمَانُ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏أَنَا أَكْفُلُ بِهِ قَالَ قَالَ بِالْوَفَاءِ ‏ ‏و قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَيْضًا ‏ ‏أَنَا أَكْفُلُ بِهِ وَقَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏","","",""],[21529,21529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُمْ ‏ ‏كَانُوا فِي مَسِيرٍ لَهُمْ فَرَأَيْتُ حِمَارَ وَحْشٍ فَرَكِبْتُ فَرَسًا وَأَخَذْتُ الرُّمْحَ فَقَتَلْتُهُ قَالَ وَفِينَا الْمُحْرِمُ قَالَ فَأَكَلُوا مِنْهُ قَالَ فَأَشْفَقُوا قَالَ فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ فَسُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَشَرْتُمْ ‏ ‏أَوْ ‏ ‏أَعَنْتُمْ ‏ ‏أَوْ ‏ ‏أَصِدْتُمْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَدْرِي قَالَ ‏ ‏أَعَنْتُمْ ‏ ‏أَوْ ‏ ‏أَصِدْتُمْ ‏ ‏ثُمَّ قَالُوا لَا فَأَمَرَهُمْ بِأَكْلِهِ ‏","","",""],[21530,21530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ إِذْ مَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ حَادَ ‏ ‏عَنْ رَاحِلَتِهِ ‏ ‏فَدَعَمْتُهُ ‏ ‏بِيَدَيَّ قَالَ فَاسْتَيْقَظَ قَالَ ثُمَّ سِرْنَا قَالَ فَمَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَمْتُهُ ‏ ‏بِيَدَيَّ فَاسْتَيْقَظَ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَقُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ حَفِظَكَ اللَّهُ كَمَا حَفِظْتَنَا مُنْذُ اللَّيْلَةِ ثُمَّ قَالَ لَا ‏ ‏أُرَانَا إِلَّا قَدْ شَقَقْنَا عَلَيْكَ نَحِّ بِنَا عَنْ الطَّرِيقِ ‏ ‏أَوْ مِلْ بِنَا عَنْ الطَّرِيقِ ‏ ‏قَالَ فَعَدَلْنَا عَنْ الطَّرِيقِ فَأَنَاخَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحِلَتَهُ فَتَوَسَّدَ كُلُّ رَجُلٍ مِنَّا ذِرَاعَ رَاحِلَتِهِ فَمَا اسْتَيْقَظْنَا حَتَّى أَشْرَقَتْ الشَّمْسُ وَذَكَرَ صَوْتَ ‏ ‏الصُّرَدِ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ هَلَكْنَا فَاتَتْنَا الصَّلَاةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ تَهْلِكُوا وَلَمْ تَفُتْكُمْ الصَّلَاةُ إِنَّمَا تَفُوتُ الْيَقْظَانَ وَلَا تَفُوتُ النَّائِمَ هَلْ مِنْ مَاءٍ قَالَ فَأَتَيْتُهُ بِسَطِيحَةٍ ‏ ‏أَوْ قَالَ ‏ ‏مَيْضَأَةٍ ‏ ‏فِيهَا مَاءٌ فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ دَفَعَهَا إِلَيَّ وَفِيهَا بَقِيَّةٌ مِنْ مَاءٍ قَالَ احْتَفِظْ بِهَا فَإِنَّهُ كَائِنٌ لَهَا نَبَأٌ وَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ تَحَوَّلَ فِي مَكَانِهِ فَأَمَرَهُ فَأَقَامَ الصَّلَاةَ فَصَلَّى صَلَاةَ الصُّبْحِ ثُمَّ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ النَّاسُ أَطَاعُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَقَدْ رَفَقُوا بِأَنْفُسِهِمْ وَأَصَابُوا وَإِنْ كَانُوا خَالَفُوهُمَا فَقَدْ خَرَقُوا بِأَنْفُسِهِمْ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏حَيْثُ فَقَدُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَا لِلنَّاسِ أَقِيمُوا بِالْمَاءِ حَتَّى تُصْبِحُوا فَأَبَوْا عَلَيْهِمَا وَانْتَهَى إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ آخِرِ النَّهَارِ وَقَدْ كَادُوا أَنْ يَهْلِكُوا عَطَشًا فَقَالُوا يَا رَسُولَ اللَّهِ هَلَكْنَا فَدَعَا ‏ ‏بِالْمِيضَأَةِ ‏ ‏ثُمَّ دَعَا بِإِنَاءٍ فَأُتِيَ بِإِنَاءٍ فَوْقَ الْقَدَحِ وَدُونَ ‏ ‏الْقَعْبِ ‏ ‏فَتَأَبَّطَهُمَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَعَلَ يَصُبُّ فِي الْإِنَاءِ ثُمَّ يَشْرَبُ الْقَوْمُ حَتَّى شَرِبُوا كُلُّهُمْ ثُمَّ نَادَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مِنْ ‏ ‏غَالٍّ ‏ ‏قَالَ ثُمَّ رَدَّ ‏ ‏الْمِيضَأَةَ ‏ ‏وَفِيهَا نَحْوٌ مِمَّا كَانَ فِيهَا قَالَ فَسَأَلْنَاهُ كَمْ كُنْتُمْ فَقَالَ كَانَ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏ثَمَانُونَ رَجُلًا وَكُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْنَيْ عَشَرَ رَجُلًا ‏","","",""],[21531,21531,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَخْبَرَهُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُلُوسًا فِي مَجْلِسٍ إِذْ مُرَّ بِجِنَازَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ مَا الْمُسْتَرِيحُ قَالَ الْعَبْدُ الْمُؤْمِنُ يَسْتَرِيحُ مِنْ نَصَبِ الدُّنْيَا وَأَذَاهَا إِلَى رَحْمَةِ اللَّهِ قُلْنَا فَمَا الْمُسْتَرَاحُ مِنْهُ قَالَ الْعَبْدُ الْفَاجِرُ يَسْتَرِيحُ مِنْهُ الْعِبَادُ وَالْبِلَادُ وَالشَّجَرُ وَالدَّوَابُّ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَقَرَأْتُهُ عَلَى ‏ ‏مَالِكٍ ‏ ‏يَعْنِي هَذَا الْحَدِيثَ ‏","","",""],[21532,21532,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَاقِي الْقَوْمِ آخِرُهُمْ ‏","","",""],[21533,21533,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ ‏","","",""],[21534,21534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏حَامِلٌ ‏ ‏أُمَامَةَ ابْنَةَ زَيْنَبَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَإِذَا رَكَعَ وَسَجَدَ وَضَعَهَا وَإِذَا قَامَ حَمَلَهَا ‏","","",""],[21535,21535,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ ‏ ‏ابْنَةِ ‏ ‏عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي حَدِيثِهِ وَكَانَتْ تَحْتَ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏دَخَلَ عَلَيْهَا فَسَكَبَتْ لَهُ وَضُوءَهُ فَجَاءَتْ هِرَّةٌ تَشْرَبُ مِنْهُ ‏ ‏فَأَصْغَى ‏ ‏لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ ‏ ‏كَبْشَةُ ‏ ‏فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ أَتَعْجَبِينَ يَا بِنْتَ أَخِي قَالَتْ نَعَمْ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّهَا مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ ‏ ‏وَالطَّوَّافَاتِ ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ ‏ ‏أَوْ ‏ ‏الطَّوَّافَاتِ ‏","","",""],[21536,21536,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْبَدٍ الزِّمَّانِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ صَوْمِهِ فَغَضِبَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا فَذَكَرَ الْحَدِيثَ ‏","","",""],[21537,21537,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبٍّ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏إِنْ كُنْتُ لَأَرَى الرُّؤْيَا تُمْرِضُنِي قَالَ فَلَقِيتُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏فَقَالَ وَأَنَا فَكُنْتُ لَأَرَى الرُّؤْيَا تُمْرِضُنِي حَتَّى سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرُّؤْيَا الصَّالِحَةُ مِنْ اللَّهِ وَإِذَا رَأَى أَحَدُكُمْ مَا يُحِبُّ فَلَا يُحَدِّثْ بِهَا إِلَّا مَنْ يُحِبُّ وَإِذَا رَأَى مَا يَكْرَهُ فَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا وَلْيَتَعَوَّذْ بِاللَّهِ مِنْ الشَّيْطَانِ الرَّجِيمِ وَشَرِّهَا وَلَا يُحَدِّثْ بِهَا أَحَدًا فَإِنَّهَا لَا تَضُرُّهُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لَهُ ‏ ‏لِيَتَعَوَّذْ بِاللَّهِ مِنْ الشَّيْطَانِ قَالَ نَعَمْ ‏","","",""],[21538,21538,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا قَتَادَةَ ‏ ‏يَقُولُ ‏ ‏بَيْنَا نَحْنُ فِي الْمَسْجِدِ جُلُوسٌ خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْمِلُ ‏ ‏أُمَامَةَ بِنْتَ أَبِي الْعَاصِ بْنِ الرَّبِيعِ ‏ ‏وَأُمُّهَا ‏ ‏زَيْنَبُ بِنْتُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ صَبِيَّةٌ ‏ ‏فَحَمَلَهَا عَلَى عَاتِقِهِ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ عَلَى عَاتِقِهِ يَضَعُهَا إِذَا رَكَعَ وَيُعِيدُهَا عَلَى عَاتِقِهِ إِذَا قَامَ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ عَلَى عَاتِقِهِ حَتَّى قَضَى صَلَاتَهُ يَفْعَلُ ذَلِكَ بِهَا ‏","","",""],[21539,21539,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا قَتَادَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَامَ فِيهِمْ ‏ ‏فَذَكَرَ لَهُمْ الْجِهَادَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَالْإِيمَانَ بِاللَّهِ مِنْ أَفْضَلِ الْأَعْمَالِ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ يُكَفِّرُ عَنِّي خَطَايَايَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ وَأَنْتَ صَابِرٌ ‏ ‏مُحْتَسِبٌ ‏ ‏مُقْبِلٌ غَيْرُ ‏ ‏مُدْبِرٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ قُلْتَ قَالَ أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ يُكَفِّرُ عَنِّي خَطَايَايَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ إِنْ قُتِلْتَ وَأَنْتَ صَابِرٌ ‏ ‏مُحْتَسِبٌ ‏ ‏مُقْبِلٌ غَيْرُ ‏ ‏مُدْبِرٍ ‏ ‏إِلَّا الدَّيْنَ فَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ لِي ذَلِكَ ‏","","",""],[21540,21540,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ ‏ ‏يُصَلِّي عَلَيْهَا فَقَالَ ‏ ‏أَعَلَيْهِ دَيْنٌ قَالُوا نَعَمْ دِينَارَانِ فَقَالَ تَرَكَ لَهُمَا وَفَاءً قَالُوا لَا قَالَ فَصَلُّوا عَلَى صَاحِبِكُمْ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏هُمَا عَلَيَّ يَا رَسُولَ اللَّهِ فَصَلَّى عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21541,21541,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الصَّوَّافُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21542,21542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ إِيَاسٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَوْمُ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏كَفَّارَةُ سَنَتَيْنِ سَنَةٍ مَاضِيَةٍ وَسَنَةٍ مُسْتَقْبَلَةٍ وَصَوْمُ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏كَفَّارَةُ سَنَةٍ ‏","","",""],[21543,21543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا قَتَادَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏وَأُمَامَةُ بِنْتُ زَيْنَبَ ابْنَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ ابْنَةُ ‏ ‏أَبِي الْعَاصِ بْنِ الرَّبِيعِ بْنِ عَبْدِ الْعُزَّى ‏ ‏عَلَى رَقَبَتِهِ فَإِذَا رَكَعَ وَضَعَهَا وَإِذَا قَامَ مِنْ سُجُودِهِ أَخَذَهَا فَأَعَادَهَا عَلَى رَقَبَتِهِ ‏ ‏فَقَالَ ‏ ‏عَامِرٌ ‏ ‏وَلَمْ أَسْأَلْهُ أَيُّ صَلَاةٍ هِيَ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَحُدِّثْتُ عَنْ ‏ ‏زَيْدِ بْنِ أَبِي عَتَّابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏أَنَّهَا صَلَاةُ الصُّبْحِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏جَوَّدَهُ ‏","","",""],[21544,21544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏فَأَحْرَمَ أَصْحَابِي وَلَمْ أُحْرِمْ فَرَأَيْتُ حِمَارًا فَحَمَلْتُ عَلَيْهِ فَاصْطَدْتُهُ فَذَكَرْتُ شَأْنَهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرْتُ أَنِّي لَمْ أَكُنْ أَحْرَمْتُ وَأَنِّي إِنَّمَا اصْطَدْتُهُ لَكَ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْحَابَهُ فَأَكَلُوا وَلَمْ يَأْكُلْ مِنْهُ حِينَ أَخْبَرْتُهُ أَنِّي اصْطَدْتُهُ لَهُ ‏","","",""],[21545,21545,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ يَعْنِي ابْنَ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاوِيَةُ ‏ ‏الْمَدِينَةَ ‏ ‏فَتَلَقَّاهُ ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَقَالَ أَمَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَالَ إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏قَالَ فَبِمَ أَمَرَكُمْ قَالَ ‏ ‏أَمَرَنَا أَنْ نَصْبِرَ قَالَ فَاصْبِرُوا إِذًا ‏","","",""],[21546,21546,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ حَلْحَلَةَ الدِّيْلِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَمُرَّ عَلَيْهِ بِجِنَازَةٍ فَقَالَ ‏ ‏مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ قَالَ قُلْنَا أَيْ رَسُولَ اللَّهِ مَا مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ قَالَ الْعَبْدُ الصَّالِحُ يَسْتَرِيحُ مِنْ ‏ ‏نَصَبِ ‏ ‏الدُّنْيَا وَهَمِّهَا إِلَى رَحْمَةِ اللَّهِ تَعَالَى وَالْعَبْدُ الْفَاجِرُ يَسْتَرِيحُ مِنْهُ الْعِبَادُ وَالْبِلَادُ وَالشَّجَرُ وَالدَّوَابُّ ‏","","",""],[21547,21547,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْقَى مِنْ الرُّؤْيَا شِدَّةً غَيْرَ أَنِّي لَا ‏ ‏أُزَمَّلُ ‏ ‏حَتَّى حَدَّثَنِي ‏ ‏أَبُو قَتَادَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرُّؤْيَا مِنْ اللَّهِ وَالْحُلْمُ مِنْ الشَّيْطَانِ فَإِذَا حَلَمَ أَحَدُكُمْ حُلْمًا يَكْرَهُهُ فَلْيَبْصُقْ عَنْ يَسَارِهِ ثَلَاثَ بَصَقَاتٍ وَلْيَسْتَعِذْ بِاللَّهِ مِنْ الشَّيْطَانِ فَإِنَّهُ لَا يَضُرُّهُ ‏","","",""],[21548,21548,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثَمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏سَمِعَ ‏ ‏عَامِرَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ ‏ ‏و حَدَّثَنَا ‏ ‏مُرَّةُ ‏ ‏فَقَالَ عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[21549,21549,"","","‏ ‏حَدَّثَنَا ‏ ‏مَخْلَدُ بْنُ يَزِيدَ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ فَارِسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَالْعَصْرِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَةٍ وَفِي الرَّكْعَتَيْنِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏","","",""],[21550,21550,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بِنَا فَيَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ فِي الْأُولَيَيْنِ بِسُورَتَيْنِ ‏ ‏وَأُمِّ الْكِتَابِ ‏ ‏وَكَانَ يُسْمِعُنَا الْأَحْيَانَ الْآيَةَ وَفِي الْآخِرَتَيْنِ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَكَانَ يُطِيلُ فِي أَوَّلِ رَكْعَةٍ مِنْ صَلَاةِ الظُّهْرِ وَصَلَاةِ الْعَصْرِ وَكَانَ يَقُولُ إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21551,21551,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏وَسُورَتَيْنِ مَعَهَا فِي الرَّكْعَتَيْنِ مِنْ صَلَاةِ الظُّهْرِ وَالْعَصْرِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَكَانَ يُطِيلُ فِي الرَّكْعَةِ الْأُولَى ‏","","",""],[21552,21552,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏كَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفُرْسَانِهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرُّؤْيَا مِنْ اللَّهِ وَالْحُلْمُ مِنْ الشَّيْطَانِ إِذَا حَلَمَ أَحَدُكُمْ الْحُلْمَ يَكْرَهُهُ فَلْيَبْصُقْ عَنْ يَسَارِهِ ثَلَاثًا وَلْيَسْتَعِذْ بِاللَّهِ مِنْهُ فَلَنْ يَضُرَّهُ ‏","","",""],[21553,21553,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاقِي الْقَوْمِ آخِرُهُمْ ‏","","",""],[21554,21554,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ التَّفْرِيطُ فِي النَّوْمِ إِنَّمَا التَّفْرِيطُ فِي الْيَقَظَةِ ‏","","",""],[21555,21555,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمِ بْنِ خَلْدَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ بَيْنَ ظَهْرَانَيْ النَّاسِ فَجَلَسْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَكَ أَنْ تَرْكَعَ رَكْعَتَيْنِ قَبْلَ أَنْ تَجْلِسَ قَالَ قُلْتُ إِنِّي رَأَيْتُكَ جَالِسًا وَالنَّاسُ جُلُوسٌ قَالَ ‏ ‏وَإِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلَا يَجْلِسْ حَتَّى يَرْكَعَ رَكْعَتَيْنِ ‏","","",""],[21556,21556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنِي ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَقُومُ فِي الصَّلَاةِ أُرِيدُ أَنْ أُطَوِّلَ فِيهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ ‏ ‏فَأَتَجَوَّزُ ‏ ‏فِي صَلَاتِي كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ ‏","","",""],[21557,21557,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏وَعَنِ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ نَفَرٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانُوا مُحْرِمِينَ إِلَّا رَجُلًا وَاحِدًا ‏ ‏فَبَصُرَ بِصَيْدٍ فَأَخَذَ سَوْطًا فَحَمَلَ عَلَيْهِ فَأَصَادَهُ فَأَكَلَ مِنْهُ وَأَكَلْنَا ثُمَّ تَزَوَّدْنَا مِنْهُ فَلَمَّا أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ إِنَّ فُلَانًا كَانَ مُحِلًّا ‏ ‏أَوْ حَلَالًا ‏ ‏فَأَصَابَ صَيْدًا وَإِنَّهُ أَكَلَ مِنْهُ وَأَكَلْنَا مَعَهُ وَمَعَنَا مِنْهُ قَالَ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مَعْبَدُ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ الْحَارِثِ بْنِ رِبْعِيٍّ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى سَيْفِ الْبَحْرِ فِي بَعْضِ عُمَرِهِ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَوَعَدَنَا أَنْ نَلْقَاهُ ‏ ‏بِقُدَيْدٍ ‏ ‏فَخَرَجْنَا وَمِنَّا الْحَلَالُ وَمِنَّا الْحَرَامُ قَالَ فَكُنْتُ حَلَالًا ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ وَفِيهِ هَذِهِ الْعَضُدُ قَدْ شَوَيْتُهَا وَأَنْضَجْتُهَا ‏ ‏وَأَطْيَبْتُهَا قَالَ فَهَاتِهَا قَالَ فَجِئْتُهُ بِهَا ‏ ‏فَنَهَسَهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ حَرَامٌ حَتَّى فَرَغَ مِنْهَا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي سَلَمَةَ ‏ ‏مَوْلَى ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ نَافِعٍ الْأَقْرَعِ ‏ ‏مَوْلَى ‏ ‏بَنِي غِفَارٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ ‏ ‏لَمْ يَزِدْ وَلَمْ يَنْقُصْ ‏","","",""],[21558,21558,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مِنْ رَآنِي فِي الْمَنَامِ فَسَيَرَانِي فِي الْيَقَظَةِ ‏ ‏أَوْ فَكَأَنَّمَا رَآنِي فِي الْيَقَظَةِ ‏ ‏لَا يَتَمَثَّلُ الشَّيْطَانُ بِي ‏ ‏فَقَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فَقَدْ رَآنِي الْحَقَّ ‏","","",""],[21559,21559,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏أَنَّهُ حَدَّثَ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَحَدَّثَنِي ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ الْأَقْرَعِ أَبِي مُحَمَّدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي غِفَارٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏رَأَيْتُ رَجُلَيْنِ يَقْتَتِلَانِ مُسْلِمٌ وَمُشْرِكٌ وَإِذَا رَجُلٌ مِنْ الْمُشْرِكِينَ يُرِيدُ أَنْ يُعِينَ صَاحِبَهُ الْمُشْرِكَ عَلَى الْمُسْلِمِ فَأَتَيْتُهُ فَضَرَبْتُ يَدَهُ فَقَطَعْتُهَا وَاعْتَنَقَنِي بِيَدِهِ الْأُخْرَى فَوَاللَّهِ مَا أَرْسَلَنِي حَتَّى وَجَدْتُ رِيحَ الْمَوْتِ فَلَوْلَا أَنَّ الدَّمَ نَزَفَهُ لَقَتَلَنِي فَسَقَطَ فَضَرَبْتُهُ فَقَتَلْتُهُ ‏ ‏وَأَجْهَضَنِي ‏ ‏عَنْهُ الْقِتَالُ وَمَرَّ بِهِ رَجُلٌ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَسَلَبَهُ فَلَمَّا فَرَغْنَا وَوَضَعَتْ الْحَرْبُ ‏ ‏أَوْزَارَهَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ قَتِيلًا فَسَلَبُهُ لَهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ قَدْ قَتَلْتُ قَتِيلًا وَأُسْلِبَ ‏ ‏فَأَجْهَضَنِي ‏ ‏عَنْهُ الْقِتَالُ فَلَا أَدْرِي مَنْ اسْتَلَبَهُ فَقَالَ رَجُلٌ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏صَدَقَ يَا رَسُولَ اللَّهِ أَنَا سَلَبْتُهُ ‏ ‏فَارْضِهِ عَنِّي مِنْ سَلَبِهِ قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏تَعْمِدُ إِلَى أَسَدٍ مِنْ أُسْدِ اللَّهِ يُقَاتِلُ عَنْ اللَّهِ عَزَّ وَجَلَّ تُقَاسِمُهُ سَلَبَهُ ارْدُدْ عَلَيْهِ سَلَبَ قَتِيلِهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ فَارْدُدْ عَلَيْهِ سَلَبَ قَتِيلِهِ قَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَأَخَذْتُهُ مِنْهُ فَبِعْتُهُ فَاشْتَرَيْتُ بِثَمَنِهِ ‏ ‏مَخْرَفًا ‏ ‏بِالْمَدِينَةِ ‏ ‏وَإِنَّهُ لَأَوَّلُ مَالٍ اعْتَقَدْتُهُ ‏","","",""],[21560,21560,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ سَمِعَ ‏ ‏جَلَبَةَ ‏ ‏رِجَالٍ فَلَمَّا صَلَّى دَعَاهُمْ فَقَالَ مَا شَأْنُكُمْ قَالُوا يَا رَسُولَ اللَّهِ اسْتَعْجَلْنَا إِلَى الصَّلَاةِ قَالَ فَلَا تَفْعَلُوا ‏ ‏إِذَا أَتَيْتُمْ الصَّلَاةَ فَعَلَيْكُمْ ‏ ‏السَّكِينَةَ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا سَبَقَكُمْ فَأَتِمُّوا ‏","","",""],[21561,21561,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏حِينَ جَعَلَ يَحْفِرُ ‏ ‏الْخَنْدَقَ ‏ ‏وَجَعَلَ يَمْسَحُ رَأْسَهُ وَيَقُولُ ‏ ‏بُؤْسَ ‏ ‏ابْنِ سُمَيَّةَ ‏ ‏تَقْتُلُكَ الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[21562,21562,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ يَحْيَى ‏ ‏مِنْ أَهْلِ ‏ ‏مَرْوَ ‏ ‏أَخْبَرَنَا ‏ ‏النَّضْرُ بْنُ شُمَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏أَبُو قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارِ بْنِ يَاسِرٍ ‏ ‏تَقْتُلُكَ الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[21563,21563,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْحُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سِرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِي سَفَرٍ ذَاتَ لَيْلَةٍ فَقُلْنَا يَا رَسُولَ اللَّهِ لَوْ ‏ ‏عَرَّسْتَ ‏ ‏بِنَا فَقَالَ إِنِّي أَخَافُ أَنْ تَنَامُوا عَنْ الصَّلَاةِ فَمَنْ يُوقِظُنَا لِلصَّلَاةِ فَقَالَ ‏ ‏بِلَالٌ ‏ ‏أَنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَعَرَّسَ ‏ ‏بِالْقَوْمِ فَاضْطَجَعْنَا وَاسْتَنَدَ ‏ ‏بِلَالٌ ‏ ‏إِلَى رَاحِلَتِهِ فَغَلَبَتْهُ عَيْنَاهُ وَاسْتَيْقَظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ طَلَعَ حَاجِبُ الشَّمْسِ فَقَالَ يَا ‏ ‏بِلَالُ ‏ ‏أَيْنَ مَا قُلْتَ لَنَا قُلْتُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُلْقِيَتْ عَلَيَّ نَوْمَةٌ مِثْلُهَا فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَبَضَ أَرْوَاحَكُمْ حِينَ شَاءَ وَرَدَّهَا عَلَيْكُمْ حِينَ شَاءَ ثُمَّ أَمَرَهُمْ فَانْتَشَرُوا لِحَاجَتِهِمْ وَتَوَضَّأَ فَارْتَفَعَتْ الشَّمْسُ فَصَلَّى بِهِمْ الْفَجْرَ ‏","","",""],[21564,21564,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ أَبِي حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ فِي طَلِيعَةٍ قِبَلَ ‏ ‏غَيْقَةَ ‏ ‏وَوَدَّانَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏وَأَبُو قَتَادَةَ ‏ ‏غَيْرُ مُحْرِمٍ فَإِذَا حِمَارُ وَحْشٍ فَطَلَبَ مِنْهُمْ سَوْطًا فَلَمْ يُنَاوِلُوهُ فَاخْتَلَسَ سَوْطَ بَعْضِهِمْ فَصَادَ حِمَارًا وَحْشِيًّا فَأَكَلُوهُ ثُمَّ لَحِقُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالْأَبْوَاءِ ‏ ‏قَالُوا إِنَّا صَنَعْنَا شَيْئًا لَا نَدْرِي مَا هُوَ فَقَالَ ‏ ‏أَطْعِمُونَا ‏","","",""],[21565,21565,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21566,21566,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ قَتَلَ رَجُلًا مِنْ الْكُفَّارِ ‏ ‏فَنَفَّلَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَبَهُ وَدِرْعَهُ فَبَاعَهُ بِخَمْسِ أَوَاقٍ ‏","","",""],[21567,21567,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏يَحْيَى بْنَ النَّضْرِ الْأَنْصَارِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا قَتَادَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏لِلْأَنْصَارِ ‏ ‏أَلَا إِنَّ النَّاسَ ‏ ‏دِثَارِي ‏ ‏وَالْأَنْصَارَ ‏ ‏شِعَارِي لَوْ سَلَكَ النَّاسُ وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبَةً ‏ ‏لَاتَّبَعْتُ ‏ ‏شِعْبَةَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَمَنْ وَلِيَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَلْيُحْسِنْ إِلَى مُحْسِنِهِمْ وَلْيَتَجَاوَزْ عَنْ مُسِيئِهِمْ وَمَنْ أَفْزَعَهُمْ فَقَدْ أَفْزَعَ هَذَا الَّذِي بَيْنَ هَاتَيْنِ وَأَشَارَ إِلَى نَفْسِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21568,21568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏وَأَنَا شَاهِدٌ عَنْ الْفَضْلِ فِي صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ جَاءَ هَذَا مِنْ قِبَلِكُمْ يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏حَدَّثَنِيهِ ‏ ‏أَبُو الْخَلِيلِ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَلِمَةً تُشْبِهُ عَدْلَ ذَلِكَ قَالَ ‏ ‏صَوْمُ ‏ ‏عَرَفَةَ ‏ ‏بِصَوْمِ سَنَتَيْنِ وَصَوْمُ ‏ ‏عَاشُورَاءَ ‏ ‏بِصَوْمِ سَنَةٍ ‏","","",""],[21569,21569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الظُّهْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَسُورَتَيْنِ وَكَانَ يُسْمِعُنَا الْأَحْيَانَ الْآيَةَ وَكَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏قَالَ وَكَانَ يُطِيلُ فِي الرَّكْعَةِ الْأُولَى مَا لَا يُطِيلُ فِي الثَّانِيَةِ وَهَكَذَا فِي صَلَاةِ الْعَصْرِ وَهَكَذَا فِي صَلَاةِ الصُّبْحِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَأَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏مِثْلَهُ سَوَاءً ‏","","",""],[21570,21570,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ خَلِيطِ ‏ ‏الْبُسْرِ ‏ ‏وَالتَّمْرِ وَعَنْ خَلِيطِ ‏ ‏الزَّبِيبِ وَالتَّمْرِ وَعَنْ خَلِيطِ ‏ ‏الزَّهْوِ ‏ ‏وَالرُّطَبِ لَهُ ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[21571,21571,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى مَيِّتٍ فَسَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏بِهَؤُلَاءِ الثَّمَانِ كَلِمَاتٍ وَزَادَ كَلِمَتَيْنِ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[21572,21572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ الزِّمَّانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ لَهُ رَجُلٌ أَرَأَيْتَ صِيَامَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ ‏ ‏أَحْتَسِبُ عِنْدَ اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الْمَاضِيَةَ وَالْبَاقِيَةَ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ صَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏قَالَ أَحْتَسِبُ عِنْدَ اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ ‏","","",""],[21573,21573,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21574,21574,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏كَانَ لَهُ عَلَى رَجُلٍ دَيْنٌ وَكَانَ يَأْتِيهِ يَتَقَاضَاهُ فَيَخْتَبِئُ مِنْهُ فَجَاءَ ذَاتَ يَوْمٍ فَخَرَجَ صَبِيٌّ فَسَأَلَهُ عَنْهُ فَقَالَ نَعَمْ هُوَ فِي الْبَيْتِ يَأْكُلُ ‏ ‏خَزِيرَةً ‏ ‏فَنَادَاهُ يَا فُلَانُ اخْرُجْ فَقَدْ أُخْبِرْتُ أَنَّكَ هَاهُنَا فَخَرَجَ إِلَيْهِ فَقَالَ مَا يُغَيِّبُكَ عَنِّي قَالَ إِنِّي مُعْسِرٌ وَلَيْسَ عِنْدِي قَالَ ‏ ‏آللَّهِ إِنَّكَ مُعْسِرٌ قَالَ نَعَمْ فَبَكَى ‏ ‏أَبُو قَتَادَةَ ‏ ‏ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَفَّسَ عَنْ غَرِيمِهِ ‏ ‏أَوْ مَحَا عَنْهُ ‏ ‏كَانَ فِي ظِلِّ الْعَرْشِ يَوْمَ الْقِيَامَةِ ‏","","",""],[21575,21575,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏كَانَ يُقَالُ لَهُ مَوْلَى ‏ ‏أَبِي قَتَادَةَ ‏ ‏وَلَمْ يَكُنْ مَوْلًى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُ أَصَابَ حِمَارَ وَحْشٍ فَسَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَقِيَ مَعَكُمْ مِنْهُ شَيْءٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ بَعْدُ فَقَالَ ‏ ‏أَبَقِيَ مَعَكُمْ مِنْهُ شَيْءٌ قَالَ فَأَكَلَهُ ‏ ‏أَوْ قَالَ فَكُلُوهُ ‏ ‏فَقُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏مَعْنَى قَوْلِهِ لَا بَأْسَ بِهِ قَالَ نَعَمْ ‏","","",""],[21576,21576,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي التَّيْمِيَّ ‏ ‏قَالَ حُدِّثْتُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَقْرَءُونَ خَلْفِي قَالُوا نَعَمْ قَالَ فَلَا تَفْعَلُوا إِلَّا ‏ ‏بِأُمِّ الْكِتَابِ ‏","","",""],[21577,21577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا ‏ ‏مُحْتَسِبًا ‏ ‏مُقْبِلًا غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏كَفَّرَ اللَّهُ بِهِ خَطَايَايَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ صَابِرًا ‏ ‏مُحْتَسِبًا ‏ ‏مُقْبِلًا غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏كَفَّرَ اللَّهُ بِهِ خَطَايَاكَ ثُمَّ إِنَّ الرَّجُلَ لَبِثَ مَا شَاءَ اللَّهُ ثُمَّ قَالَ يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ كَفَّرَ اللَّهُ بِهِ خَطَايَايَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ صَابِرًا ‏ ‏مُحْتَسِبًا ‏ ‏مُقْبِلًا غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏كَفَّرَ اللَّهُ بِهِ خَطَايَاكَ إِلَّا الدَّيْنَ كَذَلِكَ قَالَ لِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[21578,21578,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏وَأَبَانُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَالْعَصْرِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَةٍ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[21579,21579,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَنْتَبِذُوا ‏ ‏الرُّطَبَ ‏ ‏وَالزَّهْوَ ‏ ‏وَالتَّمْرَ وَالزَّبِيبَ جَمِيعًا ‏ ‏وَانْتَبِذُوا ‏ ‏كُلَّ وَاحِدٍ عَلَى حِدَتِهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَسَأَلْتُ عَنْ ‏ ‏ذَلِكَ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏فَأَخْبَرَنِي عَنْ ‏ ‏أَبِيهِ ‏ ‏بِذَلِكَ ‏","","",""],[21580,21580,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثُمَّ صَلَّى بِأَرْضِ ‏ ‏سَعْدٍ ‏ ‏بِأَصْلِ ‏ ‏الْحَرَّةِ ‏ ‏عِنْدَ بُيُوتِ السُّقْيَا ثُمَّ قَالَ ‏ ‏اللَّهُمَّ إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏خَلِيلَكَ وَعَبْدَكَ وَنَبِيَّكَ دَعَاكَ لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَبْدُكَ وَنَبِيُّكَ وَرَسُولُكَ أَدْعُوكَ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِثْلَ مَا دَعَاكَ بِهِ ‏ ‏إِبْرَاهِيمُ ‏ ‏لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏نَدْعُوكَ أَنْ تُبَارِكَ لَهُمْ فِي صَاعِهِمْ وَمُدِّهِمْ وَثِمَارِهِمْ اللَّهُمَّ حَبِّبْ إِلَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏كَمَا حَبَّبْتَ إِلَيْنَا ‏ ‏مَكَّةَ ‏ ‏وَاجْعَلْ مَا بِهَا مِنْ وَبَاءٍ ‏ ‏بِخُمٍّ ‏ ‏اللَّهُمَّ إِنِّي قَدْ حَرَّمْتُ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏كَمَا حَرَّمْتَ عَلَى لِسَانِ ‏ ‏إِبْرَاهِيمَ ‏ ‏الْحَرَمَ ‏","","",""],[21581,21581,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ رَبَاحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ لَمَّا قَامُوا إِلَى الصَّلَاةِ فَصَلَّوْا قَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوهَا الْغَدَ لِوَقْتِهَا ‏","","",""],[21582,21582,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏عَرَّسَ ‏ ‏بِلَيْلٍ اضْطَجَعَ عَلَى يَمِينِهِ وَإِذَا ‏ ‏عَرَّسَ ‏ ‏قَبْلَ الصُّبْحِ نَصَبَ ذِرَاعَيْهِ وَوَضَعَ رَأْسَهُ بَيْنَ كَفَّيْهِ ‏","","",""],[21583,21583,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَعَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏","","",""],[21584,21584,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ ‏ ‏الْخَلَاءَ ‏ ‏فَلَا يَتَمَسَّحَنَّ بِيَمِينِهِ وَإِذَا شَرِبَ فَلَا يَتَنَفَّسْ فِي إِنَائِهِ ‏","","",""],[21585,21585,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَأَى رُؤْيَا تُعْجِبُهُ فَلْيُحَدِّثْ بِهَا فَإِنَّهَا بُشْرَى مِنْ اللَّهِ عَزَّ وَجَلَّ وَمَنْ رَأَى رُؤْيَا يَكْرَهُهَا فَلَا يُحَدِّثْ بِهَا وَلْيَتْفُلْ عَنْ يَسَارِهِ وَيَتَعَوَّذْ بِاللَّهِ مِنْ شَرِّهَا ‏","","",""],[21586,21586,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَصْغَى ‏ ‏الْإِنَاءَ لِلْهِرَّةِ فَشَرِبَتْ فَقَالَ أَتَعْجَبِينَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَنَا ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّهَا مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ ‏ ‏وَالطَّوَّافَاتِ ‏","","",""],[21587,21587,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ هُوَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ وُضِعَ لَهُ وَضُوءٌ ‏ ‏فَوَلَغَ ‏ ‏فِيهِ ‏ ‏السِّنَّوْرُ ‏ ‏فَأَخَذَ يَتَوَضَّأُ فَقَالُوا يَا ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَدْ ‏ ‏وَلَغَ ‏ ‏فِيهِ ‏ ‏السِّنَّوْرُ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏السِّنَّوْرُ ‏ ‏مِنْ أَهْلِ الْبَيْتِ وَإِنَّهُ مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏أَوْ ‏ ‏الطَّوَّافَاتِ ‏ ‏عَلَيْكُمْ ‏","","",""],[21588,21588,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ وَإِذَا بَالَ أَحَدُكُمْ فَلَا يَمَسَّ ذَكَرَهُ ‏ ‏بِيَمِينِهِ وَإِذَا تَمَسَّحَ أَحَدُكُمْ مِنْ ‏ ‏الْخَلَاءِ ‏ ‏فَلَا يَتَمَسَّحَنَّ بِيَمِينِهِ ‏","","",""],[21589,21589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُحَمَّدِ بْنُ مَعْبَدِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنِ ‏ ‏ابْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا ‏ ‏أَبُو قَتَادَةَ ‏ ‏وَنَحْنُ نَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا فَقَالَ شَاهَتْ الْوُجُوهُ أَتَدْرُونَ مَا تَقُولُونَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَقَدْ قَالَ لِي ‏ ‏مُحَمَّدُ بْنُ كَعْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدِ بْنِ مَعْبَدِ بْنِ أَبِي قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏خَرَجَ عَلَيْهِمْ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[21590,21590,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُوا حَتَّى تَرَوْنِي ‏ ‏يَعْنِي لِلصَّلَاةِ ‏","","",""],[21591,21591,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ النَّوْشَجَانِ وَهُوَ أَبُو جَعْفَرٍ السُّوَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْوَأُ النَّاسِ سَرِقَةً الَّذِي يَسْرِقُ مِنْ صَلَاتِهِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَسْرِقُ مِنْ صَلَاتِهِ قَالَ لَا يُتِمُّ رُكُوعَهَا وَلَا سُجُودَهَا ‏ ‏أَوْ قَالَ لَا يُقِيمُ صُلْبَهُ فِي الرُّكُوعِ وَالسُّجُودِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[21592,21592,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةِ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعَ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرُّؤْيَا مِنْ اللَّهِ وَالْحُلْمُ مِنْ الشَّيْطَانِ فَإِذَا رَأَى أَحَدُكُمْ شَيْئًا يَكْرَهُهُ فَلْيَبْصُقْ عَنْ شِمَالِهِ ثَلَاثَ مَرَّاتٍ وَلْيَسْتَعِذْ بِاللَّهِ مِنْ شَرِّهَا فَإِنَّهَا لَنْ تَضُرَّهُ ‏","","",""],[21593,21593,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏وَعَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ وَهُوَ حَامِلٌ ابْنَةَ ‏ ‏زَيْنَبَ ‏ ‏عَلَى عُنُقِهِ فَيَؤُمُّ النَّاسَ فَإِذَا رَكَعَ وَضَعَهَا وَإِذَا قَامَ حَمَلَهَا ‏","","",""],[21594,21594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏سَمِعَ ‏ ‏أَبَاهُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏الرُّطَبُ ‏ ‏وَالزَّهْوُ ‏ ‏جَمِيعًا ‏ ‏أَوْ التَّمْرُ وَالزَّبِيبُ جَمِيعًا ‏ ‏وَقَالَ انْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا عَلَى حِدَتِهِ ‏","","",""],[21595,21595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَخْبَرَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ وَإِذَا أَتَى أَحَدُكُمْ ‏ ‏الْخَلَاءَ ‏ ‏فَلَا يَسْتَنْجِيَنَّ بِيَمِينِهِ ‏ ‏و قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏وَلَا يَمَسَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ ‏","","",""],[21596,21596,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ يُسْمِعُنَا الْآيَةَ أَحْيَانًا فَيُطِيلُ فِي الرَّكْعَةِ الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الْعَصْرِ وَيُطِيلُ فِي الرَّكْعَةِ الْأُولَى مِنْ الْفَجْرِ وَيُقَصِّرُ فِي الثَّانِيَةِ ‏","","",""],[21597,21597,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي وَعَلَيْكُمْ ‏ ‏السَّكِينَةَ ‏","","",""],[21598,21598,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَجُلًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ أَحْتَسِبُ عَلَى اللَّهِ كَفَّارَةَ سَنَتَيْنِ مَاضِيَةٍ وَمُسْتَقْبَلَةٍ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا يَصُومُ الدَّهْرَ كُلَّهُ قَالَ لَا صَامَ وَلَا أَفْطَرَ ‏ ‏أَوْ مَا صَامَ وَمَا أَفْطَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا قَالَ ذَاكَ صَوْمُ أَخِي ‏ ‏دَاوُدَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمَيْنِ قَالَ وَدِدْتُ أَنِّي طُوِّقْتُ ذَلِكَ قَالَ أَرَأَيْتَ رَجُلًا يَصُومُ يَوْمَيْنِ وَيُفْطِرُ يَوْمًا قَالَ وَمَنْ يُطِيقُ ذَلِكَ قَالَ وَسُئِلَ عَنْ صَوْمِ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏قَالَ أَحْتَسِبُ عَلَى اللَّهِ كَفَّارَةَ سَنَةٍ ‏","","",""],[21599,21599,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعُمَيْسِ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّرَقِيِّ ‏ ‏يُقَالُ لَهُ ‏ ‏عَمْرُو بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَابْنَتُهُ عَلَى عَاتِقِهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً حَمَلَ ‏ ‏أُمَامَةَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي ‏ ‏وَكَانَ إِذَا أَرَادَ أَنْ يَرْكَعَ أَوْ يَسْجُدَ وَضَعَهَا فَإِذَا قَامَ أَخَذَهَا ‏","","",""],[21600,21600,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلَا يَجْلِسْ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ ‏","","",""]];
